var _seed = 1;
function seedRandom(s)
{
  _seed = s;
}

function nextRandom()
{
  _seed = (_seed * 1664525 + 1013904223) % 4294967296;
  return _seed / 4294967296;
}

function getRandomState()
{
  return _seed;
}

function setRandomState(v)
{
  _seed = v;
}

function inBounds(x, y)
{
  if (x < 0 || y < 0 || x >= MAP_W || y >= MAP_H)
  {
    return false;
  }
  return true;
}

function keyOf(x, y)
{
  return x + "," + y;
}

function nodeIndex(layer, x, y)
{
  return (layer * MAP_H + y) * MAP_W + x;
}

function nodeLayer(idx)
{
  return Math.floor(idx / (MAP_W * MAP_H));
}

function nodeX(idx)
{
  return (idx % (MAP_W * MAP_H)) % MAP_W;
}

function nodeY(idx)
{
  return Math.floor((idx % (MAP_W * MAP_H)) / MAP_W);
}

function footprintOf(kind, dir)
{
  var f = FOOTPRINT[kind];
  if (f === undefined)
  {
    return { w: 1, h: 1 };
  }
  if (dir % 2 == 1)
  {
    return { w: f.h, h: f.w };
  }
  return { w: f.w, h: f.h };
}

function isTowerKind(kind)
{
  return TOWER_DEFS[kind] !== undefined;
}

function xpNeeded(level)
{
  return XP_PER_LEVEL * level;
}

function demandForTop(top)
{
  var d = 1;
  var i = 0;
  for (i = 0; i < DEMAND_BY_TOP_LEVEL.length; i++)
  {
    if (top >= DEMAND_BY_TOP_LEVEL[i].top)
    {
      d = DEMAND_BY_TOP_LEVEL[i].demand;
    }
  }
  return d;
}

// ---------------------------------------------------------------- ResourceNode

class ResourceNode
{
  constructor(type, x, y)
  {
    var d = NODE_DATA[type];
    this._type = type;
    this._x = x;
    this._y = y;
    this._cap = d.capacity;
    this._regen = d.regen;
    this._amt = d.capacity;
    this._depleted = false;
  }

  getType()
  {
    return this._type;
  }

  getAmount()
  {
    return this._amt;
  }

  getCapacity()
  {
    return this._cap;
  }

  getFill()
  {
    return this._amt / this._cap;
  }

  isDepleted()
  {
    return this._depleted;
  }

  take(n)
  {
    if (this._depleted)
    {
      return 0;
    }
    var got = Math.min(n, Math.floor(this._amt));
    this._amt -= got;
    if (this._amt < 1)
    {
      this._depleted = true;
    }
    return got;
  }

  toSave()
  {
    return [this._x, this._y, this._type, this._amt, this._depleted];
  }

  restore(amt, depleted)
  {
    this._amt = amt;
    this._depleted = depleted;
  }

  update(dt)
  {
    if (this._amt >= this._cap)
    {
      return;
    }
    this._amt += this._regen * dt;
    if (this._amt >= this._cap)
    {
      this._amt = this._cap;
      this._depleted = false;
    }
  }
}

// ---------------------------------------------------------------- Building

class Building
{
  constructor(kind, x, y, dir)
  {
    this._kind = kind;
    this._x = x;
    this._y = y;
    this._dir = dir;
    this._items = [];
    this._hold = null;
    this._out = null;
    this._timer = 0;
    this._rr = 0;
    this._srcX = 0;
    this._srcY = 0;
    this._ammo = 0;
    this._cool = 0;
    this._charges = 8;
    this._ore = 0;
    this._buf = [null, null, null, null];
    this._bufTime = [0, 0, 0, 0];
    this._operator = null;
    this._restocker = null;
    this._enabled = true;
    this._cargo = 0;
    this._cargoCount = 0;
    this._away = false;
    this._route = null;
    this._trip = 0;
    this._outbound = true;
    this._node = null;
    var fp = footprintOf(kind, dir);
    this._w = fp.w;
    this._h = fp.h;
    this._comfort = 0;
    this._built = false;
    this._builder = null;
    this._buildFrac = 0;
    this._stock = {};
    this._stockTotal = 0;
  }

  isBuilt()
  {
    return this._built;
  }

  setBuilt(v)
  {
    this._built = v;
  }

  getBuilder()
  {
    return this._builder;
  }

  setBuilder(w)
  {
    this._builder = w;
  }

  getBuildFrac()
  {
    return this._buildFrac;
  }

  setBuildFrac(f)
  {
    this._buildFrac = f;
  }

  getStock()
  {
    return this._stock;
  }

  getStockTotal()
  {
    return this._stockTotal;
  }

  toSave()
  {
    var d = { kind: this._kind, x: this._x, y: this._y };
    var i = 0;
    for (i = 0; i < BUILDING_SAVE_KEYS.length; i++)
    {
      d[BUILDING_SAVE_KEYS[i]] = this[BUILDING_SAVE_KEYS[i]];
    }
    return d;
  }

  restore(d)
  {
    var i = 0;
    for (i = 0; i < BUILDING_SAVE_KEYS.length; i++)
    {
      if (d[BUILDING_SAVE_KEYS[i]] !== undefined)
      {
        this[BUILDING_SAVE_KEYS[i]] = d[BUILDING_SAVE_KEYS[i]];
      }
    }
  }

  getKind()
  {
    return this._kind;
  }

  getW()
  {
    return this._w;
  }

  getH()
  {
    return this._h;
  }

  getComfort()
  {
    return this._comfort;
  }

  setComfort(c)
  {
    this._comfort = c;
  }

  getX()
  {
    return this._x;
  }

  getY()
  {
    return this._y;
  }

  getDir()
  {
    return this._dir;
  }

  setDir(d)
  {
    this._dir = d;
  }

  getItems()
  {
    return this._items;
  }

  getAmmo()
  {
    return this._ammo;
  }

  getCharges()
  {
    return this._charges;
  }

  getHold()
  {
    return this._hold;
  }

  getOut()
  {
    return this._out;
  }

  setOre(o)
  {
    this._ore = o;
  }

  getOperator()
  {
    return this._operator;
  }

  getRestocker()
  {
    return this._restocker;
  }

  setRestocker(w)
  {
    this._restocker = w;
  }

  removeStock(item, n)
  {
    var have = 0;
    if (this._stock[item] !== undefined)
    {
      have = this._stock[item];
    }
    var take = Math.min(have, n);
    this._stock[item] = have - take;
    this._stockTotal -= take;
    return take;
  }

  addStock(item, n)
  {
    var add = Math.min(STORAGE_CAPACITY - this._stockTotal, n);
    if (add <= 0)
    {
      return 0;
    }
    if (this._stock[item] === undefined)
    {
      this._stock[item] = 0;
    }
    this._stock[item] += add;
    this._stockTotal += add;
    return add;
  }

  setOperator(w)
  {
    this._operator = w;
  }

  isEnabled()
  {
    return this._enabled;
  }

  setEnabled(v)
  {
    this._enabled = v;
  }

  setNode(n)
  {
    this._node = n;
  }

  getNode()
  {
    return this._node;
  }

  addAmmo(n)
  {
    this._ammo += n;
  }

  isAway()
  {
    return this._away;
  }

  getRoute()
  {
    return this._route;
  }

  getTrip()
  {
    return this._trip;
  }

  getCargoCount()
  {
    return this._cargoCount;
  }

  addCargo(value, count, force)
  {
    if (!force && (this._away || this._cargoCount >= WAGON_CAPACITY))
    {
      return false;
    }
    this._cargo += value;
    this._cargoCount += count;
    return true;
  }

  accept(game, item, fromX, fromY)
  {
    var i = 0;
    if (!this._built)
    {
      return false;
    }
    if (this._kind == "storage")
    {
      if (this._stockTotal >= STORAGE_CAPACITY)
      {
        return false;
      }
      if (this._stock[item] === undefined)
      {
        this._stock[item] = 0;
      }
      this._stock[item] += 1;
      this._stockTotal += 1;
      return true;
    }
    if (this._kind == "belt")
    {
      var fx = this._x + DX[this._dir];
      var fy = this._y + DY[this._dir];
      if (fromX == fx && fromY == fy)
      {
        return false;
      }
      if (this._items.length >= BELT_CAPACITY)
      {
        return false;
      }
      if (this._items.length > 0)
      {
        var last = this._items[this._items.length - 1];
        if (last.pos < BELT_SPACING)
        {
          return false;
        }
      }
      this._items.push({ type: item, pos: 0 });
      return true;
    }
    if (this._kind == "router")
    {
      if (this._hold != null)
      {
        return false;
      }
      this._hold = item;
      this._srcX = fromX;
      this._srcY = fromY;
      this._timer = 0;
      return true;
    }
    if (this._kind == "junction")
    {
      var dx = this._x - fromX;
      var dy = this._y - fromY;
      for (i = 0; i < 4; i++)
      {
        if (DX[i] == dx && DY[i] == dy)
        {
          if (this._buf[i] != null)
          {
            return false;
          }
          this._buf[i] = item;
          this._bufTime[i] = 0;
          return true;
        }
      }
      return false;
    }
    if (this._kind == "trader")
    {
      return this.addCargo(ITEMS[item].price, 1, false);
    }
    if (this._kind == "smelter")
    {
      if (fromX == this._x + DX[this._dir] && fromY == this._y + DY[this._dir])
      {
        return false;
      }
      if (item != "copper" && item != "iron")
      {
        return false;
      }
      if (this._hold != null || this._out != null)
      {
        return false;
      }
      this._hold = item;
      this._timer = 0;
      return true;
    }
    if (this._kind == "tap")
    {
      if (this._hold != null)
      {
        return false;
      }
      if (fromX == this._x + DX[this._dir] && fromY == this._y + DY[this._dir])
      {
        return false;
      }
      this._hold = item;
      this._timer = 0;
      return true;
    }
    return false;
  }

  update(game, dt)
  {
    var i = 0;
    if (this._kind == "belt")
    {
      this.updateBelt(game, dt);
    }
    if (this._kind == "trader")
    {
      this.updateWagon(game, dt);
    }
    if (this._kind == "tap" && this._hold != null)
    {
      this._timer += dt;
      if (this._timer >= TAP_DELAY)
      {
        if (game.tapFeed(this, this._hold) || game.offerFront(this, this._hold))
        {
          this._hold = null;
        }
      }
    }
    if (this._kind == "drill" || this._kind == "autodrill")
    {
      var period = DRILL_PERIOD;
      if (this._kind == "autodrill")
      {
        period = AUTODRILL_PERIOD;
      }
      if (this._ore == 2)
      {
        period *= IRON_PERIOD_MUL;
      }
      var running = true;
      if (this._kind == "drill")
      {
        running = this._enabled && this._operator != null && this._operator.isOperating();
      }
      var rate = 1;
      if (this._kind == "drill" && this._operator != null)
      {
        rate = this._operator.speedMul("harvest");
      }
      if (this._hold == null && running && this._node != null && !this._node.isDepleted())
      {
        this._timer += dt * rate;
        if (this._timer >= period)
        {
          this._timer = 0;
          if (this._node.take(1) >= 1)
          {
            if (this._ore == 1)
            {
              this._hold = "copper";
            }
            else
            {
              this._hold = "iron";
            }
          }
        }
      }
      if (this._hold != null)
      {
        if (game.offerFront(this, this._hold))
        {
          this._hold = null;
        }
      }
    }
    if (this._kind == "smelter")
    {
      if (this._hold != null)
      {
        this._timer += dt;
        if (this._timer >= 2.0)
        {
          if (this._hold == "copper")
          {
            this._out = "copperBar";
          }
          else
          {
            this._out = "ironBar";
          }
          this._hold = null;
          this._timer = 0;
        }
      }
      if (this._out != null)
      {
        if (game.offerFront(this, this._out))
        {
          this._out = null;
        }
      }
    }
    if (this._kind == "router")
    {
      if (this._hold != null)
      {
        this._timer += dt;
        if (this._timer >= 0.12)
        {
          for (i = 0; i < 4; i++)
          {
            var d = (this._rr + i) % 4;
            var nx = this._x + DX[d];
            var ny = this._y + DY[d];
            if (nx == this._srcX && ny == this._srcY)
            {
              continue;
            }
            var nb = game.getBuilding(nx, ny);
            if (nb != null && nb.accept(game, this._hold, this._x, this._y))
            {
              this._hold = null;
              this._rr = (d + 1) % 4;
              break;
            }
          }
        }
      }
    }
    if (this._kind == "junction")
    {
      for (i = 0; i < 4; i++)
      {
        if (this._buf[i] != null)
        {
          this._bufTime[i] += dt;
          if (this._bufTime[i] >= 0.15)
          {
            var jb = game.getBuilding(this._x + DX[i], this._y + DY[i]);
            if (jb != null && jb.accept(game, this._buf[i], this._x, this._y))
            {
              this._buf[i] = null;
            }
          }
        }
      }
    }
    if (isTowerKind(this._kind))
    {
      this.updateTower(game, dt);
    }
    if (this._kind == "trap")
    {
      this._cool -= dt;
      if (this._cool <= 0)
      {
        var enemies = game.getEnemies();
        for (i = 0; i < enemies.length; i++)
        {
          var e = enemies[i];
          if (e.isFlying() || e.isDead())
          {
            continue;
          }
          if (Math.floor(e.getX()) == this._x && Math.floor(e.getY()) == this._y)
          {
            e.hurt(TRAP_DAMAGE, "trap");
            e.slow(TRAP_SLOW, TRAP_SLOW_TIME);
            this._charges -= 1;
            this._cool = 0.4;
            game.addFloater(this._x + 0.5, this._y + 0.3, "snap!", "#ffd27a", LAYER_SURFACE);
            break;
          }
        }
        if (this._charges <= 0)
        {
          game.removeBuildingAt(this._x, this._y, false, LAYER_SURFACE);
        }
      }
    }
  }

  updateTower(game, dt)
  {
    var def = TOWER_DEFS[this._kind];
    this._cool -= dt;
    if (this._cool > 0 || this._ammo <= 0)
    {
      return;
    }
    var rate = game.towerRate(this);
    if (rate <= 0)
    {
      return;
    }
    var target = game.findTarget(this._x + 0.5, this._y + 0.5, def.range, def);
    if (target == null)
    {
      return;
    }
    game.fireTower(this, target);
    this._cool = def.cooldown / rate;
  }

  updateWagon(game, dt)
  {
    if (!this._away)
    {
      if (this._cargoCount == 0)
      {
        return;
      }
      if (this._timer < 0)
      {
        this._timer += dt;
        return;
      }
      this._timer += dt;
      if (this._cargoCount < WAGON_CAPACITY && this._timer < WAGON_MAX_WAIT)
      {
        return;
      }
      this._timer = 0;
      var route = game.routeToGate(this._x, this._y);
      if (route == null)
      {
        game.addFloater(this._x + 0.5, this._y, "no route to Gate", "#ff9a8a");
        this._timer = -3;
        return;
      }
      this._route = route;
      this._trip = 0;
      this._outbound = true;
      this._away = true;
      return;
    }
    var last = this._route.length - 1;
    if (this._outbound)
    {
      this._trip += WAGON_SPEED * dt;
      if (this._trip >= last)
      {
        this._trip = last;
        game.cashIn(this._cargo, GATE_X, GATE_Y);
        this._cargo = 0;
        this._cargoCount = 0;
        this._outbound = false;
      }
      return;
    }
    this._trip -= WAGON_SPEED * dt;
    if (this._trip <= 0)
    {
      this._trip = 0;
      this._away = false;
      this._route = null;
    }
  }

  updateBelt(game, dt)
  {
    var i = 0;
    for (i = 0; i < this._items.length; i++)
    {
      var it = this._items[i];
      var maxPos = 1;
      if (i > 0)
      {
        maxPos = this._items[i - 1].pos - BELT_SPACING;
      }
      it.pos += BELT_SPEED * dt;
      if (it.pos > maxPos)
      {
        it.pos = maxPos;
      }
    }
    if (this._items.length > 0)
    {
      var front = this._items[0];
      if (front.pos >= 1)
      {
        var nb = game.getBuilding(this._x + DX[this._dir], this._y + DY[this._dir]);
        if (nb != null && nb.accept(game, front.type, this._x, this._y))
        {
          this._items.shift();
        }
      }
    }
  }
}

// ------------------------------------------------------------------- Enemy

class Enemy
{
  constructor(type, x, y, hpMul)
  {
    var t = ENEMY_TYPES[type];
    this._type = type;
    this._x = x;
    this._y = y;
    this._maxHp = t.hp * hpMul;
    this._hp = this._maxHp;
    this._speed = t.speed;
    this._flying = t.flying;
    this._size = t.size;
    this._color = t.color;
    this._boss = t.boss;
    this._dead = false;
    this._slowAmt = 0;
    this._slowT = 0;
    this._wob = nextRandom() * 6;
    this._facing = 1;
    this._cause = "tower";
  }

  getX()
  {
    return this._x;
  }

  getY()
  {
    return this._y;
  }

  getHp()
  {
    return this._hp;
  }

  getMaxHp()
  {
    return this._maxHp;
  }

  getSize()
  {
    return this._size;
  }

  getColor()
  {
    return this._color;
  }

  getType()
  {
    return this._type;
  }

  getWobble()
  {
    return this._wob;
  }

  getFacing()
  {
    return this._facing;
  }

  getCause()
  {
    return this._cause;
  }

  isFlying()
  {
    return this._flying;
  }

  isBoss()
  {
    return this._boss;
  }

  isDead()
  {
    return this._dead;
  }

  restore(hp, maxHp)
  {
    this._hp = hp;
    this._maxHp = maxHp;
  }

  slow(amount, time)
  {
    if (this._slowT <= 0 || amount >= this._slowAmt)
    {
      this._slowAmt = amount;
    }
    this._slowT = Math.max(this._slowT, time);
  }

  hurt(amount, cause)
  {
    this._hp -= amount;
    if (this._hp <= 0 && !this._dead)
    {
      this._dead = true;
      if (cause !== undefined)
      {
        this._cause = cause;
      }
    }
  }

  update(game, dt)
  {
    if (this._dead)
    {
      return;
    }
    this._wob += dt * 9;
    if (this._slowT > 0)
    {
      this._slowT -= dt;
    }
    var tx = Math.floor(this._x);
    var ty = Math.floor(this._y);
    if (tx == GATE_X && ty == GATE_Y)
    {
      game.enemyReachedGate();
      return;
    }
    var best = game.bestStep(tx, ty);
    if (best == null)
    {
      return;
    }
    var cx = best.x + 0.5;
    var cy = best.y + 0.5;
    var dx = cx - this._x;
    var dy = cy - this._y;
    var len = Math.sqrt(dx * dx + dy * dy);
    if (dx > 0.01)
    {
      this._facing = 1;
    }
    else if (dx < -0.01)
    {
      this._facing = -1;
    }
    var slowMul = 1;
    if (this._slowT > 0)
    {
      slowMul = 1 - this._slowAmt;
    }
    var step = this._speed * slowMul * dt;
    if (len <= step)
    {
      this._x = cx;
      this._y = cy;
    }
    else
    {
      this._x += (dx / len) * step;
      this._y += (dy / len) * step;
    }
  }
}

// ------------------------------------------------------------------ Worker

class Worker
{
  constructor(x, y, name)
  {
    this._name = name;
    this._skills = {};
    var talent = Math.floor(nextRandom() * SKILLS.length);
    var si = 0;
    for (si = 0; si < SKILLS.length; si++)
    {
      var lvl = 1;
      if (nextRandom() < 0.3)
      {
        lvl += 1;
      }
      if (si == talent)
      {
        lvl += 2;
      }
      this._skills[SKILLS[si].id] = { level: lvl, xp: 0, on: true };
    }
    this._bed = null;
    this._site = null;
    this._moodMul = MOOD_NO_BED;
    this._x = x;
    this._y = y;
    this._state = "idle";
    this._path = [];
    this._job = null;
    this._order = null;
    this._post = null;
    this._carryType = null;
    this._carryCount = 0;
    this._tower = null;
    this._haulItem = null;
    this._progress = 0;
    this._think = 0;
    this._wob = nextRandom() * 6;
    this._layer = LAYER_UNDER;
    this._facing = 1;
  }

  getX()
  {
    return this._x;
  }

  getY()
  {
    return this._y;
  }

  getState()
  {
    return this._state;
  }

  getLayer()
  {
    return this._layer;
  }

  getFacing()
  {
    return this._facing;
  }

  getWobble()
  {
    return this._wob;
  }

  getCarryType()
  {
    return this._carryType;
  }

  getCarryCount()
  {
    return this._carryCount;
  }

  isOperating()
  {
    return this._state == "operate";
  }

  isGunning()
  {
    return this._state == "gun";
  }

  getPost()
  {
    return this._post;
  }

  getTower()
  {
    return this._tower;
  }

  getName()
  {
    return this._name;
  }

  toSave()
  {
    return { x: this._x, y: this._y, name: this._name, layer: this._layer, skills: this._skills };
  }

  restoreSave(d)
  {
    var i = 0;
    this._layer = d.layer;
    for (i = 0; i < SKILLS.length; i++)
    {
      if (d.skills[SKILLS[i].id] !== undefined)
      {
        this._skills[SKILLS[i].id] = d.skills[SKILLS[i].id];
      }
    }
  }

  getSkill(id)
  {
    return this._skills[id];
  }

  isOn(id)
  {
    return this._skills[id].on;
  }

  toggleSkill(id)
  {
    this._skills[id].on = !this._skills[id].on;
  }

  getBed()
  {
    return this._bed;
  }

  setBed(b)
  {
    this._bed = b;
  }

  getMoodMul()
  {
    return this._moodMul;
  }

  setMoodMul(m)
  {
    this._moodMul = m;
  }

  speedMul(id)
  {
    return (1 + SKILL_STEP * (this._skills[id].level - 1)) * this._moodMul;
  }

  getTopLevel()
  {
    var top = 1;
    var i = 0;
    for (i = 0; i < SKILLS.length; i++)
    {
      if (this._skills[SKILLS[i].id].level > top)
      {
        top = this._skills[SKILLS[i].id].level;
      }
    }
    return top;
  }

  getDemand()
  {
    return demandForTop(this.getTopLevel());
  }

  gainXp(game, id, dt)
  {
    var sk = this._skills[id];
    if (sk.level >= MAX_SKILL_LEVEL)
    {
      return;
    }
    sk.xp += dt * XP_RATE;
    if (sk.xp >= xpNeeded(sk.level))
    {
      sk.xp -= xpNeeded(sk.level);
      sk.level += 1;
      game.addFloater(this._x, this._y - 0.8, this._name + ": " + this.skillName(id) + " " + sk.level, "#ffe27a", this._layer);
      game.addLog(this._name + " reached " + this.skillName(id) + " level " + sk.level + ".");
    }
  }

  skillName(id)
  {
    var i = 0;
    for (i = 0; i < SKILLS.length; i++)
    {
      if (SKILLS[i].id == id)
      {
        return SKILLS[i].name;
      }
    }
    return id;
  }

  release()
  {
    if (this._job != null)
    {
      this._job.claimed = false;
      this._job = null;
    }
    if (this._order != null)
    {
      this._order.occupied = false;
      this._order = null;
    }
    if (this._post != null)
    {
      if (this._post.getOperator() === this)
      {
        this._post.setOperator(null);
      }
      this._post = null;
    }
    if (this._site != null)
    {
      if (this._site.getBuilder() === this)
      {
        this._site.setBuilder(null);
      }
      this._site = null;
    }
    if (this._tower != null)
    {
      if (this._tower.getRestocker() === this)
      {
        this._tower.setRestocker(null);
      }
      this._tower = null;
    }
    if (this._state == "walkFetch" || this._state == "walkHaul")
    {
      this._carryCount = 0;
      this._carryType = null;
    }
    this._haulItem = null;
    this._path = [];
    this._state = "idle";
    this._think = 0;
  }

  follow(dt)
  {
    this._wob += dt * 12;
    if (this._path.length == 0)
    {
      return true;
    }
    var next = this._path[0];
    var cx = next.x + 0.5;
    var cy = next.y + 0.5;
    var dx = cx - this._x;
    var dy = cy - this._y;
    var len = Math.sqrt(dx * dx + dy * dy);
    if (dx > 0.01)
    {
      this._facing = 1;
    }
    else if (dx < -0.01)
    {
      this._facing = -1;
    }
    var step = 3.2 * dt;
    if (len <= step)
    {
      this._x = cx;
      this._y = cy;
      this._layer = next.l;
      this._path.shift();
    }
    else
    {
      this._x += (dx / len) * step;
      this._y += (dy / len) * step;
    }
    return false;
  }

  update(game, dt)
  {
    var tx = Math.floor(this._x);
    var ty = Math.floor(this._y);
    var st = this._state;

    if (st == "idle")
    {
      this._think -= dt;
      if (this._think > 0)
      {
        return;
      }
      this._think = 0.4;
      var site = null;
      if (this.isOn("construction"))
      {
        site = game.findBuildJob(tx, ty, this._layer);
      }
      if (site != null)
      {
        this._site = site.site;
        this._site.setBuilder(this);
        this._path = site.path;
        this._state = "walkBuild";
        return;
      }
      var towerJob = null;
      if (this.isOn(TOWER_SKILL))
      {
        towerJob = game.findTowerJob(tx, ty, this._layer);
      }
      if (towerJob != null)
      {
        this._tower = towerJob.tower;
        this._path = towerJob.path;
        if (towerJob.mode == "man")
        {
          this._post = towerJob.tower;
          this._post.setOperator(this);
          this._state = "walkGun";
        }
        else
        {
          this._tower.setRestocker(this);
          this._haulItem = towerJob.item;
          this._state = "walkFetch";
        }
        return;
      }
      var post = null;
      if (this.isOn("harvest"))
      {
        post = game.findStaffingPost(tx, ty, this._layer);
      }
      if (post != null)
      {
        this._post = post.post;
        this._post.setOperator(this);
        this._path = post.path;
        this._state = "walkPost";
        return;
      }
      var found = null;
      if (this.isOn("excavate"))
      {
        found = game.findDigJob(tx, ty, this._layer);
      }
      if (found != null)
      {
        this._job = found.job;
        this._job.claimed = true;
        this._path = found.path;
        this._state = "walk";
        return;
      }
      var mine = null;
      if (this.isOn("harvest"))
      {
        mine = game.findMineOrder(tx, ty, this._layer);
      }
      if (mine != null)
      {
        this._order = mine.order;
        this._order.occupied = true;
        this._path = mine.path;
        this._state = "walkMine";
      }
      return;
    }

    if ((st == "walkBuild" || st == "build") && !game.isSiteValid(this, this._site))
    {
      this.release();
      return;
    }
    if ((st == "walk" || st == "dig") && !game.isJobActive(this._job))
    {
      this.release();
      return;
    }
    if ((st == "walkGun" || st == "gun") && (!game.isTowerManned(this, this._post) || !this.isOn(TOWER_SKILL)))
    {
      this.release();
      return;
    }
    if ((st == "walkFetch" || st == "walkHaul") && (!game.isHaulValid(this) || !this.isOn(TOWER_SKILL)))
    {
      this.release();
      return;
    }
    if ((st == "walkPost" || st == "operate") && (!game.isPostValid(this, this._post) || !this.isOn("harvest")))
    {
      this.release();
      return;
    }
    if ((st == "walkMine" || st == "mining") && !game.isOrderActive(this._order))
    {
      this.release();
      return;
    }

    if (st == "walkBuild")
    {
      if (this.follow(dt))
      {
        this._state = "build";
        this._progress = 0;
        var siteMid = this._site.getX() + this._site.getW() / 2;
        if (Math.abs(siteMid - this._x) > 0.01)
        {
          this._facing = siteMid > this._x ? 1 : -1;
        }
      }
      return;
    }
    if (st == "build")
    {
      this._wob += dt * 16;
      this._progress += dt * this.speedMul("construction");
      this.gainXp(game, "construction", dt);
      var need = game.buildTime(this._site);
      this._site.setBuildFrac(Math.min(1, this._progress / need));
      if (this._progress >= need)
      {
        game.completeBuild(this._site);
        this._site.setBuilder(null);
        this._site = null;
        this._state = "idle";
        this._think = 0;
      }
      return;
    }
    if (st == "walk")
    {
      if (this.follow(dt))
      {
        this._state = "dig";
        this._progress = 0;
        if (Math.abs(this._job.x + 0.5 - this._x) > 0.01)
        {
          this._facing = this._job.x + 0.5 > this._x ? 1 : -1;
        }
      }
      return;
    }
    if (st == "dig")
    {
      this._wob += dt * 16;
      this._progress += dt * this.speedMul("excavate");
      this.gainXp(game, "excavate", dt);
      if (this._progress >= game.jobTime(this._job))
      {
        game.completeDig(this._job, this._x, this._y);
        this._job = null;
        this._state = "idle";
        this._think = 0;
      }
      return;
    }
    if (st == "walkPost")
    {
      if (this.follow(dt))
      {
        this._state = "operate";
      }
      return;
    }
    if (st == "operate")
    {
      this._wob += dt * 10;
      this._think -= dt;
      if (this._think <= 0)
      {
        this._think = 1;
        if (this.isOn("construction") && game.findBuildJob(tx, ty, this._layer) != null)
        {
          this.release();
          return;
        }
      }
      var rig = this._post;
      if (rig.getNode() != null && !rig.getNode().isDepleted() && rig.getHold() == null)
      {
        this.gainXp(game, "harvest", dt);
      }
      return;
    }
    if (st == "walkGun")
    {
      if (this.follow(dt))
      {
        this._state = "gun";
        this._think = 0.5;
      }
      return;
    }
    if (st == "gun")
    {
      this._wob += dt * 6;
      this._think -= dt;
      if (this._think <= 0)
      {
        this._think = 0.5;
        if (this._post.getAmmo() <= game.towerLowAmmo(this._post))
        {
          var fetchPlan = game.planFetch(tx, ty, this._layer, this._post);
          if (fetchPlan != null)
          {
            this._tower = this._post;
            this._haulItem = fetchPlan.item;
            this._path = fetchPlan.path;
            this._state = "walkFetch";
          }
        }
      }
      return;
    }
    if (st == "walkFetch")
    {
      if (this.follow(dt))
      {
        var want = game.fetchAmount(this._tower, this._haulItem);
        var taken = 0;
        if (want > 0)
        {
          taken = game.takeFromStorage(this._haulItem, want);
        }
        if (taken == 0)
        {
          this.release();
          return;
        }
        this._carryType = this._haulItem;
        this._carryCount = taken;
        var standPath = game.pathToTowerStand(Math.floor(this._x), Math.floor(this._y), this._layer, this._tower);
        if (standPath == null)
        {
          game.stashItem(this._carryType, this._carryCount);
          this._carryCount = 0;
          this._carryType = null;
          this.release();
          return;
        }
        this._path = standPath;
        this._state = "walkHaul";
      }
      return;
    }
    if (st == "walkHaul")
    {
      if (this.follow(dt))
      {
        var haulTower = this._tower;
        var haulShots = game.shotsFor(haulTower, this._carryType) * this._carryCount;
        haulTower.addAmmo(haulShots);
        game.addFloater(haulTower.getX() + 0.5, haulTower.getY(), "+" + haulShots + " ammo", "#ffd27a", LAYER_SURFACE);
        this._carryCount = 0;
        this._carryType = null;
        if (this._post === haulTower && game.getRaid() != null)
        {
          this._state = "gun";
          this._think = 0.5;
        }
        else
        {
          this.release();
        }
      }
      return;
    }
    if (st == "walkMine")
    {
      if (this.follow(dt))
      {
        this._state = "mining";
        this._progress = 0;
        if (Math.abs(this._order.x + 0.5 - this._x) > 0.01)
        {
          this._facing = this._order.x + 0.5 > this._x ? 1 : -1;
        }
      }
      return;
    }
    if (st == "mining")
    {
      this._wob += dt * 16;
      this._progress += dt * this.speedMul("harvest");
      this.gainXp(game, "harvest", dt);
      if (this._progress >= game.mineHaulTime())
      {
        this._carryType = this._order.type;
        this._carryCount = game.harvestNode(this._order.x, this._order.y, game.getPick().cap);
        this._order.occupied = false;
        this._order = null;
        if (this._carryCount == 0)
        {
          this._carryType = null;
          this._state = "idle";
          return;
        }
        var back = game.findPathToWagon(tx, ty, this._layer);
        if (back == null)
        {
          this._carryCount = 0;
          this._carryType = null;
          this._state = "idle";
          return;
        }
        this._path = back;
        this._state = "carry";
      }
      return;
    }
    if (st == "carry")
    {
      if (this.follow(dt))
      {
        game.deliver(this._carryType, this._carryCount, this._x, this._y);
        this._carryCount = 0;
        this._carryType = null;
        this._state = "idle";
        this._think = 0;
      }
    }
  }
}

// -------------------------------------------------------------------- Game

class Game
{
  constructor(seed)
  {
    seedRandom(seed);
    this._tiles = [];
    this._ore = [];
    this._gridDown = [];
    this._gridUp = [];
    this._surface = [];
    this._nodeAt = [];
    this._nodes = [];
    this._unlocked = [];
    this._expandCredits = 0;
    this._buildings = [];
    this._queue = [];
    this._workers = [];
    this._enemies = [];
    this._floaters = [];
    this._shots = [];
    this._blasts = [];
    this._corpses = [];
    this._log = [];
    this._dist = [];
    this._flowDirty = true;
    this._credits = 150;
    this._stone = 30;
    this._time = 0;
    this._unlockedIron = false;
    this._raid = null;
    this._wins = 0;
    this._losses = 0;
    this._regions = 0;
    this._premium = { soulglass: 0, embersteel: 0, moonroot: 0 };
    this._sales = [];
    this._hidden = {};
    this._orders = [];
    this._tech = {};
    this._wagon = null;
    this._comfortT = 0;
    this.initClaims();
    this.generate();
    this.rollHidden();
    this.addWorker();
    this.addWorker();
    this.addLog("The Short King's hold is mostly rock. Start by building the Trade Wagon.");
  }

  // ---- getters for the renderer and UI

  getTile(x, y)
  {
    return this._tiles[y][x];
  }

  getOre(x, y)
  {
    return this._ore[y][x];
  }

  getBuilding(x, y)
  {
    if (!inBounds(x, y))
    {
      return null;
    }
    return this._gridDown[y][x];
  }

  getUpper(x, y)
  {
    if (!inBounds(x, y))
    {
      return null;
    }
    return this._gridUp[y][x];
  }

  getNode(x, y)
  {
    return this._nodeAt[y][x];
  }

  harvestNode(x, y, n)
  {
    var node = this._nodeAt[y][x];
    if (node == null)
    {
      return 0;
    }
    return node.take(n);
  }

  isUnlocked(x, y)
  {
    if (!inBounds(x, y))
    {
      return false;
    }
    return this._unlocked[Math.floor(y / BLOCK_TILES)][Math.floor(x / BLOCK_TILES)];
  }

  getClaims()
  {
    return this._expandCredits;
  }

  hasClaimedNeighbor(bx, by)
  {
    var d = 0;
    for (d = 0; d < 4; d++)
    {
      var nx = bx + DX[d];
      var ny = by + DY[d];
      if (nx >= 0 && ny >= 0 && nx < BLOCKS_X && ny < BLOCKS_Y && this._unlocked[ny][nx])
      {
        return true;
      }
    }
    return false;
  }

  canExpand(bx, by)
  {
    if (bx < 0 || by < 0 || bx >= BLOCKS_X || by >= BLOCKS_Y)
    {
      return "Out of bounds";
    }
    if (this._unlocked[by][bx])
    {
      return "Already yours";
    }
    if (this._expandCredits <= 0)
    {
      return "Win a raid to earn an expansion";
    }
    if (!this.hasClaimedNeighbor(bx, by))
    {
      return "Must touch land you already hold";
    }
    return "";
  }

  getExpandable()
  {
    var list = [];
    var bx = 0;
    var by = 0;
    for (by = 0; by < BLOCKS_Y; by++)
    {
      for (bx = 0; bx < BLOCKS_X; bx++)
      {
        if (!this._unlocked[by][bx] && this.hasClaimedNeighbor(bx, by))
        {
          list.push({ bx: bx, by: by });
        }
      }
    }
    return list;
  }

  cmdExpand(x, y)
  {
    if (!inBounds(x, y))
    {
      return "Out of bounds";
    }
    var bx = Math.floor(x / BLOCK_TILES);
    var by = Math.floor(y / BLOCK_TILES);
    var why = this.canExpand(bx, by);
    if (why != "")
    {
      return why;
    }
    this._unlocked[by][bx] = true;
    this._expandCredits -= 1;
    this._flowDirty = true;
    this.addLog("The hold grows: a new " + BLOCK_TILES + "x" + BLOCK_TILES + " block is yours, surface and underground.");
    return "ok";
  }

  getHousing()
  {
    var beds = 0;
    var i = 0;
    for (i = 0; i < this._buildings.length; i++)
    {
      if (this._buildings[i].getKind() == "bed" && this._buildings[i].isBuilt())
      {
        beds += 1;
      }
    }
    return BASE_HOUSING + beds;
  }

  getSurface(x, y)
  {
    return this._surface[y][x];
  }

  getBuildings()
  {
    return this._buildings;
  }

  getQueue()
  {
    return this._queue;
  }

  getWorkers()
  {
    return this._workers;
  }

  getEnemies()
  {
    return this._enemies;
  }

  getFloaters()
  {
    return this._floaters;
  }

  getShots()
  {
    return this._shots;
  }

  getBlasts()
  {
    return this._blasts;
  }

  getCorpses()
  {
    return this._corpses;
  }

  getRaid()
  {
    return this._raid;
  }

  getCredits()
  {
    return this._credits;
  }

  getStone()
  {
    return this._stone;
  }

  getWins()
  {
    return this._wins;
  }

  getLosses()
  {
    return this._losses;
  }

  getRegions()
  {
    return this._regions;
  }

  getPremium()
  {
    return this._premium;
  }

  getTier()
  {
    return this._wins + 1;
  }

  isIronUnlocked()
  {
    return this._unlockedIron;
  }

  getLog()
  {
    return this._log;
  }

  getTime()
  {
    return this._time;
  }

  getHidden(rivalId)
  {
    return this._hidden[rivalId];
  }

  getIncomePerMinute()
  {
    var total = 0;
    var i = 0;
    for (i = 0; i < this._sales.length; i++)
    {
      total += this._sales[i].amount;
    }
    return Math.round((total / 30) * 60);
  }

  getHireCost()
  {
    return 100 * (this._workers.length - 1);
  }

  // ---- generation

  generate()
  {
    var x = 0;
    var y = 0;
    for (y = 0; y < MAP_H; y++)
    {
      this._tiles.push([]);
      this._ore.push([]);
      this._gridDown.push([]);
      this._gridUp.push([]);
      this._nodeAt.push([]);
      this._surface.push([]);
      this._dist.push([]);
      for (x = 0; x < MAP_W; x++)
      {
        this._tiles[y].push(T_ROCK);
        this._ore[y].push(0);
        this._gridDown[y].push(null);
        this._gridUp[y].push(null);
        this._nodeAt[y].push(null);
        if (y >= SURFACE_ROW)
        {
          this._surface[y].push(S_OPEN);
        }
        else
        {
          this._surface[y].push(S_MOUNTAIN);
        }
        this._dist[y].push(-1);
      }
    }
    for (y = 28; y <= 30; y++)
    {
      for (x = 17; x <= 23; x++)
      {
        this._tiles[y][x] = T_FLOOR;
      }
    }
    this._tiles[GATE_Y][GATE_X] = T_FLOOR;
    this._surface[GATE_Y][GATE_X] = S_OPEN;

    // Guaranteed copper next to the starting chamber so nobody digs blind
    var startCopper = [[16, 28], [15, 28], [16, 27], [15, 27], [16, 26], [24, 28], [25, 28], [24, 27], [25, 27], [25, 26]];
    var i = 0;
    for (i = 0; i < startCopper.length; i++)
    {
      this._ore[startCopper[i][1]][startCopper[i][0]] = 1;
    }

    // Random clusters. Deeper (smaller y) leans iron.
    var k = 0;
    for (k = 0; k < 26; k++)
    {
      var cx = 2 + Math.floor(nextRandom() * 36);
      var cy = 3 + Math.floor(nextRandom() * 24);
      var type = 1;
      if (cy < 20 && nextRandom() < 0.7)
      {
        type = 2;
      }
      this.seedCluster(cx, cy, type, 4 + Math.floor(nextRandom() * 5));
    }

    // Ore under the open ground, for belts that have to reach the defenses
    for (k = 0; k < 4; k++)
    {
      var ex = 3 + Math.floor(nextRandom() * 34);
      var ey = 33 + Math.floor(nextRandom() * 5);
      var etype = 1;
      if (k == 3)
      {
        etype = 2;
      }
      this.seedCluster(ex, ey, etype, 4 + Math.floor(nextRandom() * 3));
    }
    this.createNodes();
    this.generateSurface();
  }

  initClaims()
  {
    var bx = 0;
    var by = 0;
    for (by = 0; by < BLOCKS_Y; by++)
    {
      this._unlocked.push([]);
      for (bx = 0; bx < BLOCKS_X; bx++)
      {
        var open = bx >= START_BLOCKS.x0 && bx <= START_BLOCKS.x1 && by >= START_BLOCKS.y0 && by <= START_BLOCKS.y1;
        this._unlocked[by].push(open);
      }
    }
  }

  createNodes()
  {
    var x = 0;
    var y = 0;
    for (y = 0; y < MAP_H; y++)
    {
      for (x = 0; x < MAP_W; x++)
      {
        if (this._ore[y][x] > 0)
        {
          var node = new ResourceNode(this._ore[y][x], x, y);
          this._nodeAt[y][x] = node;
          this._nodes.push(node);
        }
      }
    }
  }

  seedCluster(cx, cy, type, size)
  {
    var s = 0;
    for (s = 0; s < size; s++)
    {
      if (inBounds(cx, cy) && this._tiles[cy][cx] == T_ROCK && cx > 0 && cx < MAP_W - 1 && cy > 0 && cy < MAP_H - 1)
      {
        this._ore[cy][cx] = type;
      }
      var d = Math.floor(nextRandom() * 4);
      cx += DX[d];
      cy += DY[d];
    }
  }

  generateSurface()
  {
    var x = 0;
    var y = 0;
    for (y = SURFACE_ROW; y < MAP_H - 1; y++)
    {
      for (x = 1; x < MAP_W - 1; x++)
      {
        if (Math.abs(x - GATE_X) <= 1 && y <= SURFACE_ROW + 2)
        {
          continue;
        }
        var r = nextRandom();
        if (r < TREE_CHANCE)
        {
          this._surface[y][x] = S_TREE;
        }
        else if (r < TREE_CHANCE + BOULDER_CHANCE)
        {
          this._surface[y][x] = S_BOULDER;
        }
      }
    }
    this.recomputeFlow();
    if (!this.spawnReachable())
    {
      for (y = SURFACE_ROW; y < MAP_H; y++)
      {
        this._surface[y][GATE_X] = S_OPEN;
      }
      this._flowDirty = true;
    }
  }

  rollHidden()
  {
    var id = "";
    for (id in RIVALS)
    {
      var n = RIVALS[id].waves.length;
      this._hidden[id] = Math.floor(nextRandom() * (n - 1));
    }
  }

  addWorker()
  {
    var wx = 17.5 + (this._workers.length % 6);
    var n = this._workers.length;
    var name = DWARF_NAMES[n % DWARF_NAMES.length];
    if (n >= DWARF_NAMES.length)
    {
      name += " " + (Math.floor(n / DWARF_NAMES.length) + 1);
    }
    this._workers.push(new Worker(wx, 29.5, name));
  }

  addLog(text)
  {
    this._log.push({ text: text, t: this._time });
    if (this._log.length > 30)
    {
      this._log.shift();
    }
  }

  addFloater(x, y, text, color, layer)
  {
    if (this._floaters.length > 40)
    {
      return;
    }
    if (layer === undefined)
    {
      layer = LAYER_UNDER;
    }
    this._floaters.push({ x: x, y: y, text: text, color: color, life: 1.6, layer: layer });
  }

  addShot(x1, y1, x2, y2)
  {
    this._shots.push({ x1: x1, y1: y1, x2: x2, y2: y2, life: 0.1 });
  }

  // A dead enemy leaves a short death animation behind. Only types with sprites get one.
  addCorpse(e)
  {
    var def = ENEMY_SPRITES[e.getType()];
    if (def === undefined)
    {
      return;
    }
    var cause = e.getCause();
    var count = def.deathTower.length;
    if (cause == "trap")
    {
      count = def.deathTrap.length;
    }
    if (this._corpses.length >= MAX_CORPSES)
    {
      this._corpses.shift();
    }
    this._corpses.push({ type: e.getType(), x: e.getX(), y: e.getY(), facing: e.getFacing(), cause: cause, t: 0, life: count / def.deathRate + CORPSE_HOLD });
  }

  addBlast(x, y, r)
  {
    this._blasts.push({ x: x, y: y, r: r, life: 0.35 });
  }

  // ---- pathing

  isWalkable(layer, x, y)
  {
    if (!inBounds(x, y) || !this.isUnlocked(x, y))
    {
      return false;
    }
    if (layer == LAYER_UNDER)
    {
      return this._tiles[y][x] == T_FLOOR;
    }
    var sf = this._surface[y][x];
    if (sf != S_OPEN && sf != S_ROOM)
    {
      return false;
    }
    var b = this._gridUp[y][x];
    if (b != null && (b.getKind() == "wall" || isTowerKind(b.getKind())))
    {
      return false;
    }
    return true;
  }

  recomputeFlow()
  {
    var x = 0;
    var y = 0;
    for (y = 0; y < MAP_H; y++)
    {
      for (x = 0; x < MAP_W; x++)
      {
        this._dist[y][x] = -1;
      }
    }
    var qx = [GATE_X];
    var qy = [GATE_Y];
    this._dist[GATE_Y][GATE_X] = 0;
    var head = 0;
    while (head < qx.length)
    {
      var cx = qx[head];
      var cy = qy[head];
      head++;
      var d = 0;
      for (d = 0; d < 4; d++)
      {
        var nx = cx + DX[d];
        var ny = cy + DY[d];
        if (this.isWalkable(LAYER_SURFACE, nx, ny) && this._dist[ny][nx] == -1)
        {
          this._dist[ny][nx] = this._dist[cy][cx] + 1;
          qx.push(nx);
          qy.push(ny);
        }
      }
    }
    this._flowDirty = false;
  }

  spawnReachable()
  {
    var x = 0;
    for (x = 1; x < MAP_W - 1; x++)
    {
      if (this._dist[MAP_H - 1][x] >= 0)
      {
        return true;
      }
    }
    return false;
  }

  bestStep(tx, ty)
  {
    if (this._flowDirty)
    {
      this.recomputeFlow();
    }
    var best = null;
    var bestDist = 999999;
    var d = 0;
    for (d = 0; d < 4; d++)
    {
      var nx = tx + DX[d];
      var ny = ty + DY[d];
      if (inBounds(nx, ny) && this._dist[ny][nx] >= 0 && this._dist[ny][nx] < bestDist)
      {
        bestDist = this._dist[ny][nx];
        best = { x: nx, y: ny };
      }
    }
    return best;
  }

  flowDistAt(tx, ty)
  {
    if (!inBounds(tx, ty))
    {
      return 999999;
    }
    var v = this._dist[ty][tx];
    if (v < 0)
    {
      return 999999;
    }
    return v;
  }

  // ---- placement

  wouldSealPath(kind, x, y)
  {
    if (kind != "wall" && !isTowerKind(kind))
    {
      return false;
    }
    var temp = new Building(kind, x, y, 0);
    this._gridUp[y][x] = temp;
    this.recomputeFlow();
    var sealed = !this.spawnReachable();
    this._gridUp[y][x] = null;
    this.recomputeFlow();
    return sealed;
  }

  sightClear(x1, y1, x2, y2)
  {
    var dx = x2 - x1;
    var dy = y2 - y1;
    var len = Math.sqrt(dx * dx + dy * dy);
    var steps = Math.ceil(len / SIGHT_STEP);
    var sx = Math.floor(x1);
    var sy = Math.floor(y1);
    var ex = Math.floor(x2);
    var ey = Math.floor(y2);
    var i = 0;
    for (i = 1; i < steps; i++)
    {
      var tx = Math.floor(x1 + (dx * i) / steps);
      var ty = Math.floor(y1 + (dy * i) / steps);
      if ((tx == sx && ty == sy) || (tx == ex && ty == ey))
      {
        continue;
      }
      if (!inBounds(tx, ty))
      {
        return false;
      }
      var t = this._surface[ty][tx];
      if (t == S_TREE || t == S_BOULDER || t == S_MOUNTAIN)
      {
        return false;
      }
    }
    return true;
  }

  costFor(kind)
  {
    if (kind == "trader" && this._wagon == null)
    {
      return { credits: 0, stone: 0 };
    }
    return COSTS[kind];
  }

  cellReason(kind, x, y)
  {
    if (!inBounds(x, y))
    {
      return "Out of bounds";
    }
    if (!this.isUnlocked(x, y))
    {
      return "Beyond your claim. Win a raid to expand";
    }
    var layer = BUILD_LAYER[kind];
    var existing = null;
    if (layer == LAYER_UNDER)
    {
      if (this._tiles[y][x] != T_FLOOR)
      {
        return "Dig it out first";
      }
      existing = this._gridDown[y][x];
    }
    else
    {
      var surf = this._surface[y][x];
      var rule = PLACE_RULE[kind];
      if (rule == "room")
      {
        if (surf != S_ROOM)
        {
          var f = footprintOf(kind, 0);
          if (f.w > 1 || f.h > 1)
          {
            return "Needs a " + f.w + "x" + f.h + " excavated room (R rotates)";
          }
          return "Needs a room: excavate the mountain surface first";
        }
      }
      else if (rule == "any")
      {
        if (surf != S_ROOM && surf != S_OPEN)
        {
          return "Goes in a room or on open ground";
        }
      }
      else
      {
        if (surf == S_MOUNTAIN || surf == S_ROOM)
        {
          return "Defenses go outside the mountain";
        }
        if (surf == S_TREE)
        {
          return "Clear the tree first";
        }
        if (surf == S_BOULDER)
        {
          return "Clear the boulder first";
        }
      }
      if (x == GATE_X && y == GATE_Y)
      {
        return "That is the Gate";
      }
      existing = this._gridUp[y][x];
    }
    if (existing != null)
    {
      if (existing.getKind() == kind && DIRECTIONAL[kind])
      {
        return "rot";
      }
      return "Occupied";
    }
    return "";
  }

  canPlace(kind, x, y, dir)
  {
    if (dir === undefined)
    {
      dir = 0;
    }
    var fp = footprintOf(kind, dir);
    var cx = 0;
    var cy = 0;
    for (cy = 0; cy < fp.h; cy++)
    {
      for (cx = 0; cx < fp.w; cx++)
      {
        var cell = this.cellReason(kind, x + cx, y + cy);
        if (cell == "rot")
        {
          return "";
        }
        if (cell != "")
        {
          return cell;
        }
      }
    }
    if (kind == "trader")
    {
      if (y > 30)
      {
        return "Place it inside the mountain";
      }
      if (this._wagon == null && Math.max(Math.abs(x - GATE_X), Math.abs(y - GATE_Y)) > 8)
      {
        return "Place the first wagon near the Gate";
      }
    }
    else if (this._wagon == null)
    {
      return "Build the Trade Wagon first";
    }
    if (kind == "drill" && !this._tech.manned)
    {
      return "Needs the Mounted Drill Rig upgrade";
    }
    if (kind == "autodrill" && !this._tech.auto)
    {
      return "Needs the Steam Automaton upgrade";
    }
    if (kind == "tap" && !this._tech.autoload)
    {
      return "Needs the Belt Loader Rig upgrade";
    }
    if (kind == "drill" || kind == "autodrill")
    {
      var ore = this._ore[y][x];
      if (ore == 0)
      {
        return "Drills need an ore node";
      }
      if (ore == 2 && !this._unlockedIron)
      {
        return "Iron is locked. Win a raid first";
      }
    }
    var cost = this.costFor(kind);
    if (this._credits < cost.credits || this._stone < cost.stone)
    {
      return "Cannot afford";
    }
    var itemWhy = this.itemsReason(cost.items);
    if (itemWhy != "")
    {
      return itemWhy;
    }
    if (this.wouldSealPath(kind, x, y))
    {
      return "That would seal the path";
    }
    return "";
  }

  cmdPlace(kind, x, y, dir)
  {
    var reason = this.canPlace(kind, x, y, dir);
    if (reason != "")
    {
      return reason;
    }
    var grid = this._gridDown;
    if (BUILD_LAYER[kind] == LAYER_SURFACE)
    {
      grid = this._gridUp;
    }
    var existing = grid[y][x];
    if (existing != null)
    {
      existing.setDir(dir);
      return "rot";
    }
    var cost = this.costFor(kind);
    this._credits -= cost.credits;
    this._stone -= cost.stone;
    this.payItems(cost.items);
    var b = new Building(kind, x, y, dir);
    if (kind == "drill" || kind == "autodrill")
    {
      b.setOre(this._ore[y][x]);
      b.setNode(this._nodeAt[y][x]);
    }
    if (kind == "trader" && this._wagon == null)
    {
      this._wagon = b;
    }
    var cx = 0;
    var cy = 0;
    for (cy = 0; cy < b.getH(); cy++)
    {
      for (cx = 0; cx < b.getW(); cx++)
      {
        grid[y + cy][x + cx] = b;
      }
    }
    this._buildings.push(b);
    this._flowDirty = true;
    return "ok";
  }


  removeBuildingAt(x, y, fullRefund, layer)
  {
    if (!inBounds(x, y))
    {
      return false;
    }
    var grid = this._gridDown;
    if (layer == LAYER_SURFACE)
    {
      grid = this._gridUp;
    }
    var b = grid[y][x];
    if (b == null || (b === this._wagon && b.isBuilt()))
    {
      return false;
    }
    if (b.getOperator() != null)
    {
      b.getOperator().release();
    }
    if (b.getBuilder() != null)
    {
      b.getBuilder().release();
    }
    var cost = COSTS[b.getKind()];
    if (b === this._wagon)
    {
      cost = { credits: 0, stone: 0 };
      this._wagon = null;
    }
    if (fullRefund || !b.isBuilt())
    {
      this._credits += cost.credits;
      this._stone += cost.stone;
    }
    else
    {
      this._credits += Math.floor(cost.credits / 2);
      this._stone += Math.floor(cost.stone / 2);
    }
    if (cost.items !== undefined)
    {
      var refundFrac = 0.5;
      if (fullRefund || !b.isBuilt())
      {
        refundFrac = 1;
      }
      var refundId = "";
      for (refundId in cost.items)
      {
        this.stashItem(refundId, Math.floor(cost.items[refundId] * refundFrac));
      }
    }
    var fx = 0;
    var fy = 0;
    for (fy = 0; fy < b.getH(); fy++)
    {
      for (fx = 0; fx < b.getW(); fx++)
      {
        if (grid[b.getY() + fy][b.getX() + fx] === b)
        {
          grid[b.getY() + fy][b.getX() + fx] = null;
        }
      }
    }
    var i = this._buildings.indexOf(b);
    if (i >= 0)
    {
      this._buildings.splice(i, 1);
    }
    this._flowDirty = true;
    return true;
  }

  cmdErase(x, y, layer)
  {
    var i = 0;
    for (i = 0; i < this._queue.length; i++)
    {
      if (this._queue[i].x == x && this._queue[i].y == y && this._queue[i].layer == layer)
      {
        this._queue.splice(i, 1);
        return;
      }
    }
    if (layer == LAYER_UNDER)
    {
      for (i = 0; i < this._orders.length; i++)
      {
        if (this._orders[i].x == x && this._orders[i].y == y)
        {
          this._orders.splice(i, 1);
          return;
        }
      }
    }
    this.removeBuildingAt(x, y, false, layer);
  }

  cmdUndoPlace(x, y, layer)
  {
    this.removeBuildingAt(x, y, true, layer);
  }

  cmdHire()
  {
    if (this._workers.length >= this.getHousing())
    {
      return "No free bed. Excavate a room and build a Bed (Rooms)";
    }
    var cost = this.getHireCost();
    if (this._credits < cost)
    {
      return "Cannot afford";
    }
    this._credits -= cost;
    this.addWorker();
    return "ok";
  }

  // ---- housing, comfort, skills

  cellIsFloor(x, y)
  {
    if (!inBounds(x, y) || !this.isUnlocked(x, y))
    {
      return false;
    }
    if (x == GATE_X && y == GATE_Y)
    {
      return false;
    }
    var sf = this._surface[y][x];
    return sf == S_ROOM || sf == S_OPEN;
  }

  boxFree(bed, ox, oy, w, h)
  {
    var cx = 0;
    var cy = 0;
    for (cy = 0; cy < h; cy++)
    {
      for (cx = 0; cx < w; cx++)
      {
        var tx = ox + cx;
        var ty = oy + cy;
        if (!this.cellIsFloor(tx, ty))
        {
          return false;
        }
        var b = this._gridUp[ty][tx];
        if (b != null && b !== bed && b.getKind() != "desk" && b.getKind() != "lantern")
        {
          return false;
        }
      }
    }
    return true;
  }

  hasSpace(bed, w, h)
  {
    var ox = 0;
    var oy = 0;
    for (oy = bed.getY() - h + 1; oy <= bed.getY(); oy++)
    {
      for (ox = bed.getX() - w + 1; ox <= bed.getX(); ox++)
      {
        if (this.boxFree(bed, ox, oy, w, h))
        {
          return true;
        }
      }
    }
    return false;
  }

  nearCounts(bed)
  {
    var n = { desk: 0, decor: 0, walls: 0, door: 0 };
    var dx = 0;
    var dy = 0;
    for (dy = -COMFORT_RADIUS; dy <= COMFORT_RADIUS; dy++)
    {
      for (dx = -COMFORT_RADIUS; dx <= COMFORT_RADIUS; dx++)
      {
        var tx = bed.getX() + dx;
        var ty = bed.getY() + dy;
        if (!inBounds(tx, ty) || this._surface[ty][tx] == S_MOUNTAIN)
        {
          n.walls += 1;
          continue;
        }
        var b = this._gridUp[ty][tx];
        if (b == null || !b.isBuilt())
        {
          continue;
        }
        if (b.getKind() == "wall")
        {
          n.walls += 1;
        }
        if (b.getKind() == "desk")
        {
          n.desk += 1;
        }
        if (b.getKind() == "lantern")
        {
          n.decor += 1;
        }
        if (b.getKind() == "door")
        {
          n.door += 1;
        }
      }
    }
    return n;
  }

  unmetFor(bed, req)
  {
    var sp = req.space;
    if (!this.hasSpace(bed, sp[0], sp[1]) && !this.hasSpace(bed, sp[1], sp[0]))
    {
      return "a clear " + sp[0] + "x" + sp[1] + " space (desks and lanterns may sit in it)";
    }
    var n = this.nearCounts(bed);
    if (n.desk < req.desk)
    {
      return req.desk + " desk within " + COMFORT_RADIUS + " tiles";
    }
    if (n.walls < req.walls)
    {
      return req.walls + " wall or rock tiles within " + COMFORT_RADIUS + " tiles";
    }
    if (n.decor < req.decor)
    {
      return req.decor + " lanterns within " + COMFORT_RADIUS + " tiles";
    }
    if (n.door < req.door)
    {
      return "a door within " + COMFORT_RADIUS + " tiles";
    }
    return "";
  }

  bedComfort(bed)
  {
    var level = 0;
    var i = 0;
    for (i = 0; i < COMFORT_LEVELS.length; i++)
    {
      if (this.unmetFor(bed, COMFORT_LEVELS[i]) != "")
      {
        break;
      }
      level = i + 1;
    }
    return level;
  }

  comfortReport(bed)
  {
    var lvl = bed.getComfort();
    if (lvl >= COMFORT_LEVELS.length)
    {
      return "Bed comfort " + lvl + " (max)";
    }
    return "Bed comfort " + lvl + ". Next level needs " + this.unmetFor(bed, COMFORT_LEVELS[lvl]);
  }

  moodFor(w)
  {
    var bed = w.getBed();
    if (bed == null)
    {
      return MOOD_NO_BED;
    }
    if (bed.getComfort() >= w.getDemand())
    {
      return MOOD_CONTENT;
    }
    return MOOD_CRAMPED;
  }

  updateHousing()
  {
    var beds = [];
    var i = 0;
    var j = 0;
    for (i = 0; i < this._buildings.length; i++)
    {
      if (this._buildings[i].getKind() == "bed" && this._buildings[i].isBuilt())
      {
        this._buildings[i].setComfort(this.bedComfort(this._buildings[i]));
        beds.push(this._buildings[i]);
      }
    }
    var taken = [];
    for (i = 0; i < this._workers.length; i++)
    {
      var bed = this._workers[i].getBed();
      if (bed != null && beds.indexOf(bed) < 0)
      {
        this._workers[i].setBed(null);
      }
      if (this._workers[i].getBed() != null)
      {
        taken.push(this._workers[i].getBed());
      }
    }
    var order = this._workers.slice();
    order.sort(function(a, b)
    {
      return b.getDemand() - a.getDemand();
    });
    for (i = 0; i < order.length; i++)
    {
      if (order[i].getBed() != null)
      {
        continue;
      }
      var best = null;
      for (j = 0; j < beds.length; j++)
      {
        if (taken.indexOf(beds[j]) >= 0)
        {
          continue;
        }
        if (best == null || beds[j].getComfort() > best.getComfort())
        {
          best = beds[j];
        }
      }
      if (best != null)
      {
        order[i].setBed(best);
        taken.push(best);
      }
    }
    for (i = 0; i < this._workers.length; i++)
    {
      this._workers[i].setMoodMul(this.moodFor(this._workers[i]));
    }
  }

  cmdToggleSkill(index, skillId)
  {
    if (index < 0 || index >= this._workers.length)
    {
      return "No such dwarf";
    }
    if (this._workers[index].getSkill(skillId) === undefined)
    {
      return "No such skill";
    }
    this._workers[index].toggleSkill(skillId);
    return "ok";
  }

  drillStatus(b)
  {
    if (!b.isEnabled())
    {
      return "Staffing is switched off for this drill";
    }
    var op = b.getOperator();
    var i = 0;
    if (op == null)
    {
      var any = false;
      for (i = 0; i < this._workers.length; i++)
      {
        if (this._workers[i].isOn("harvest"))
        {
          any = true;
        }
      }
      if (!any)
      {
        return "No dwarf has Harvesting switched on (Dwarves panel, C)";
      }
      return "Waiting for a free dwarf with a path to this drill";
    }
    if (!op.isOperating())
    {
      return op.getName() + " is on the way";
    }
    if (b.getNode() != null && b.getNode().isDepleted())
    {
      return "Node depleted, refilling";
    }
    if (b.getHold() != null)
    {
      return "Output blocked: put a belt in front of the arrow";
    }
    return "Running, manned by " + op.getName();
  }

  // ---- raid progress and saving

  getRaidRemaining()
  {
    var raid = this._raid;
    if (raid == null)
    {
      return 0;
    }
    var left = this._enemies.length + raid.queue.length;
    var w = 0;
    for (w = raid.waveIdx + 1; w < raid.waves.length; w++)
    {
      left += raid.waves[w].length;
    }
    return left;
  }

  // Returns plain data that shares arrays with the live game. Stringify it right away.
  toSave()
  {
    var out = { version: SAVE_VERSION, mapW: MAP_W, mapH: MAP_H };
    var i = 0;
    out.tiles = this._tiles;
    out.ore = this._ore;
    out.surface = this._surface;
    out.unlocked = this._unlocked;
    out.nodes = [];
    for (i = 0; i < this._nodes.length; i++)
    {
      out.nodes.push(this._nodes[i].toSave());
    }
    out.buildings = [];
    for (i = 0; i < this._buildings.length; i++)
    {
      out.buildings.push(this._buildings[i].toSave());
    }
    out.wagon = this._buildings.indexOf(this._wagon);
    out.workers = [];
    for (i = 0; i < this._workers.length; i++)
    {
      out.workers.push(this._workers[i].toSave());
    }
    out.queue = [];
    for (i = 0; i < this._queue.length; i++)
    {
      out.queue.push({ x: this._queue[i].x, y: this._queue[i].y, layer: this._queue[i].layer });
    }
    out.orders = [];
    for (i = 0; i < this._orders.length; i++)
    {
      out.orders.push({ x: this._orders[i].x, y: this._orders[i].y, type: this._orders[i].type });
    }
    out.enemies = [];
    for (i = 0; i < this._enemies.length; i++)
    {
      var e = this._enemies[i];
      out.enemies.push({ type: e.getType(), x: e.getX(), y: e.getY(), hp: e.getHp(), maxHp: e.getMaxHp() });
    }
    out.raid = this._raid;
    out.credits = this._credits;
    out.stone = this._stone;
    out.time = this._time;
    out.unlockedIron = this._unlockedIron;
    out.wins = this._wins;
    out.losses = this._losses;
    out.regions = this._regions;
    out.expandCredits = this._expandCredits;
    out.premium = this._premium;
    out.tech = this._tech;
    out.hidden = this._hidden;
    out.log = this._log.slice(-10);
    out.rng = getRandomState();
    return out;
  }

  applySave(d)
  {
    var x = 0;
    var y = 0;
    var i = 0;
    this._tiles = d.tiles;
    this._ore = d.ore;
    this._surface = d.surface;
    this._unlocked = d.unlocked;
    this._gridDown = [];
    this._gridUp = [];
    this._nodeAt = [];
    for (y = 0; y < MAP_H; y++)
    {
      this._gridDown.push([]);
      this._gridUp.push([]);
      this._nodeAt.push([]);
      for (x = 0; x < MAP_W; x++)
      {
        this._gridDown[y].push(null);
        this._gridUp[y].push(null);
        this._nodeAt[y].push(null);
      }
    }
    this._nodes = [];
    for (i = 0; i < d.nodes.length; i++)
    {
      var nd = d.nodes[i];
      var node = new ResourceNode(nd[2], nd[0], nd[1]);
      node.restore(nd[3], nd[4]);
      this._nodeAt[nd[1]][nd[0]] = node;
      this._nodes.push(node);
    }
    this._buildings = [];
    for (i = 0; i < d.buildings.length; i++)
    {
      var bd = d.buildings[i];
      if (bd.kind == "tower")
      {
        bd.kind = "crossbow";
      }
      var b = new Building(bd.kind, bd.x, bd.y, bd._dir);
      b.restore(bd);
      if (bd.kind == "drill" || bd.kind == "autodrill")
      {
        b.setNode(this._nodeAt[bd.y][bd.x]);
      }
      var grid = this._gridDown;
      if (BUILD_LAYER[bd.kind] == LAYER_SURFACE)
      {
        grid = this._gridUp;
      }
      var cx = 0;
      var cy = 0;
      for (cy = 0; cy < b.getH(); cy++)
      {
        for (cx = 0; cx < b.getW(); cx++)
        {
          grid[bd.y + cy][bd.x + cx] = b;
        }
      }
      this._buildings.push(b);
    }
    this._wagon = null;
    if (d.wagon >= 0)
    {
      this._wagon = this._buildings[d.wagon];
    }
    this._workers = [];
    for (i = 0; i < d.workers.length; i++)
    {
      var wd = d.workers[i];
      var w = new Worker(wd.x, wd.y, wd.name);
      w.restoreSave(wd);
      this._workers.push(w);
    }
    this._queue = [];
    for (i = 0; i < d.queue.length; i++)
    {
      this._queue.push({ x: d.queue[i].x, y: d.queue[i].y, layer: d.queue[i].layer, claimed: false });
    }
    this._orders = [];
    for (i = 0; i < d.orders.length; i++)
    {
      this._orders.push({ x: d.orders[i].x, y: d.orders[i].y, type: d.orders[i].type, occupied: false });
    }
    this._enemies = [];
    for (i = 0; i < d.enemies.length; i++)
    {
      var en = new Enemy(d.enemies[i].type, d.enemies[i].x, d.enemies[i].y, 1);
      en.restore(d.enemies[i].hp, d.enemies[i].maxHp);
      this._enemies.push(en);
    }
    this._raid = d.raid;
    this._credits = d.credits;
    this._stone = d.stone;
    this._time = d.time;
    this._unlockedIron = d.unlockedIron;
    this._wins = d.wins;
    this._losses = d.losses;
    this._regions = d.regions;
    this._expandCredits = d.expandCredits;
    this._premium = d.premium;
    this._tech = d.tech;
    this._hidden = d.hidden;
    this._log = d.log;
    this._floaters = [];
    this._shots = [];
    this._blasts = [];
    this._corpses = [];
    this._sales = [];
    this._comfortT = 0;
    this._flowDirty = true;
    setRandomState(d.rng);
  }

  static fromSave(d)
  {
    if (d == null || d.version != SAVE_VERSION || d.mapW != MAP_W || d.mapH != MAP_H)
    {
      return null;
    }
    var g = new Game(1);
    g.applySave(d);
    return g;
  }

  // ---- construction

  findBuildJob(sx, sy, sl)
  {
    var res = null;
    var bestSite = null;
    var bestDist = 999999;
    var bestX = 0;
    var bestY = 0;
    var bestL = 0;
    var i = 0;
    for (i = 0; i < this._buildings.length; i++)
    {
      var b = this._buildings[i];
      if (b.isBuilt() || b.getBuilder() != null)
      {
        continue;
      }
      if (res == null)
      {
        res = this.bfsFrom(sx, sy, sl);
      }
      var layer = BUILD_LAYER[b.getKind()];
      var cx = 0;
      var cy = 0;
      var n = 0;
      for (cy = 0; cy < b.getH(); cy++)
      {
        for (cx = 0; cx < b.getW(); cx++)
        {
          for (n = 0; n < 5; n++)
          {
            var ax = b.getX() + cx;
            var ay = b.getY() + cy;
            if (n < 4)
            {
              ax += DX[n];
              ay += DY[n];
            }
            if (!inBounds(ax, ay))
            {
              continue;
            }
            var d = res.dist[nodeIndex(layer, ax, ay)];
            if (d >= 0 && d < bestDist)
            {
              bestDist = d;
              bestSite = b;
              bestX = ax;
              bestY = ay;
              bestL = layer;
            }
          }
        }
      }
    }
    if (bestSite == null)
    {
      return null;
    }
    return { site: bestSite, path: this.pathFromBfs(res, bestL, bestX, bestY) };
  }

  isSiteValid(worker, b)
  {
    if (b == null)
    {
      return false;
    }
    return !b.isBuilt() && this._buildings.indexOf(b) >= 0 && b.getBuilder() === worker;
  }

  buildTime(b)
  {
    var t = BUILD_TIME[b.getKind()];
    if (t === undefined)
    {
      return 3;
    }
    return t;
  }

  completeBuild(b)
  {
    b.setBuilt(true);
    b.setBuildFrac(1);
    this._flowDirty = true;
    this.addFloater(b.getX() + 0.5, b.getY() + 0.2, "built", "#7fe0ff", BUILD_LAYER[b.getKind()]);
    if (b === this._wagon)
    {
      this.addLog("The Trade Wagon is ready for cargo.");
    }
  }

  siteStatus(b)
  {
    var builder = b.getBuilder();
    var i = 0;
    if (builder == null)
    {
      for (i = 0; i < this._workers.length; i++)
      {
        if (this._workers[i].isOn("construction"))
        {
          return "Blueprint: waiting for a free dwarf with a path to it";
        }
      }
      return "Blueprint: no dwarf has Construction switched on (Dwarves panel, C)";
    }
    return "Blueprint: " + builder.getName() + " is on it (" + Math.floor(b.getBuildFrac() * 100) + "%)";
  }

  storageReport(b)
  {
    var parts = [];
    var id = "";
    for (id in b.getStock())
    {
      if (b.getStock()[id] > 0)
      {
        parts.push(ITEMS[id].name + " " + b.getStock()[id]);
      }
    }
    var text = "Storage " + b.getStockTotal() + "/" + STORAGE_CAPACITY;
    if (parts.length > 0)
    {
      text += ": " + parts.join(", ");
    }
    return text;
  }

  // ---- digging

  digReason(x, y, layer)
  {
    if (!inBounds(x, y))
    {
      return "Out of bounds";
    }
    if (!this.isUnlocked(x, y))
    {
      return "Beyond your claim. Win a raid to expand";
    }
    if (x <= 0 || x >= MAP_W - 1 || y <= 0 || y >= MAP_H - 1)
    {
      return "Map edge";
    }
    if (layer == LAYER_UNDER)
    {
      if (this._tiles[y][x] != T_ROCK)
      {
        return "Already open";
      }
      return "";
    }
    if (this._surface[y][x] != S_MOUNTAIN)
    {
      return "Nothing to excavate";
    }
    if (y > MAX_ROOM_ROW)
    {
      return "Rooms go deeper inside the mountain";
    }
    return "";
  }

  cmdDig(x, y, layer)
  {
    if (layer === undefined)
    {
      layer = LAYER_UNDER;
    }
    if (this.digReason(x, y, layer) != "")
    {
      return;
    }
    if (this.isQueued(x, y, layer))
    {
      return;
    }
    this._queue.push({ x: x, y: y, layer: layer, claimed: false });
  }

  cmdClear(x, y)
  {
    if (!inBounds(x, y) || !this.isUnlocked(x, y))
    {
      return;
    }
    var t = this._surface[y][x];
    if (t != S_TREE && t != S_BOULDER)
    {
      return;
    }
    if (this.isQueued(x, y, LAYER_SURFACE))
    {
      return;
    }
    this._queue.push({ x: x, y: y, layer: LAYER_SURFACE, claimed: false });
  }

  isQueued(x, y, layer)
  {
    var i = 0;
    for (i = 0; i < this._queue.length; i++)
    {
      if (this._queue[i].x == x && this._queue[i].y == y && this._queue[i].layer == layer)
      {
        return true;
      }
    }
    return false;
  }

  digTime(y)
  {
    return (1.0 + Math.max(0, 31 - y) * 0.04) * this.getPick().digMul;
  }

  jobTime(job)
  {
    if (job.layer == LAYER_UNDER || this._surface[job.y][job.x] == S_MOUNTAIN)
    {
      return this.digTime(job.y);
    }
    var base = CLEAR_TREE_TIME;
    if (this._surface[job.y][job.x] == S_BOULDER)
    {
      base = CLEAR_BOULDER_TIME;
    }
    return base * this.getPick().digMul;
  }

  isJobActive(job)
  {
    return this._queue.indexOf(job) >= 0;
  }

  findDigJob(sx, sy, sl)
  {
    if (this._queue.length == 0)
    {
      return null;
    }
    var res = this.bfsFrom(sx, sy, sl);
    var bestJob = null;
    var bestDist = 999999;
    var bestX = 0;
    var bestY = 0;
    var j = 0;
    for (j = 0; j < this._queue.length; j++)
    {
      var job = this._queue[j];
      if (job.claimed)
      {
        continue;
      }
      var n = 0;
      for (n = 0; n < 4; n++)
      {
        var ax = job.x + DX[n];
        var ay = job.y + DY[n];
        if (!inBounds(ax, ay))
        {
          continue;
        }
        var d = res.dist[nodeIndex(job.layer, ax, ay)];
        if (d >= 0 && d < bestDist)
        {
          bestDist = d;
          bestJob = job;
          bestX = ax;
          bestY = ay;
        }
      }
    }
    if (bestJob == null)
    {
      return null;
    }
    return { job: bestJob, path: this.pathFromBfs(res, bestJob.layer, bestX, bestY) };
  }

  completeDig(job, wx, wy)
  {
    var i = this._queue.indexOf(job);
    if (i >= 0)
    {
      this._queue.splice(i, 1);
    }
    if (job.layer == LAYER_UNDER)
    {
      this._tiles[job.y][job.x] = T_FLOOR;
      this._stone += 2;
      this.addFloater(job.x + 0.5, job.y + 0.5, "+2 stone", "#cfc6b8", LAYER_UNDER);
    }
    else
    {
      var was = this._surface[job.y][job.x];
      if (was == S_MOUNTAIN)
      {
        this._surface[job.y][job.x] = S_ROOM;
        this._stone += 2;
        this.addFloater(job.x + 0.5, job.y + 0.5, "+2 stone", "#cfc6b8", LAYER_SURFACE);
      }
      else
      {
        this._surface[job.y][job.x] = S_OPEN;
      }
      if (was == S_BOULDER)
      {
        this._stone += BOULDER_STONE;
        this.addFloater(job.x + 0.5, job.y + 0.5, "+" + BOULDER_STONE + " stone", "#cfc6b8", LAYER_SURFACE);
      }
      else if (was == S_TREE)
      {
        this.addFloater(job.x + 0.5, job.y + 0.5, "cleared", "#9be07a", LAYER_SURFACE);
      }
    }
    this._flowDirty = true;
    if (nextRandom() < 0.12)
    {
      var line = BARKS[Math.floor(nextRandom() * BARKS.length)];
      this.addFloater(wx, wy - 0.6, line, "#ffe9b0", job.layer);
    }
  }

  // ---- economy

  offer(from, item)
  {
    var i = 0;
    for (i = 0; i < 4; i++)
    {
      var d = (from._rr + i) % 4;
      var nb = this.getBuilding(from.getX() + DX[d], from.getY() + DY[d]);
      if (nb != null && nb.accept(this, item, from.getX(), from.getY()))
      {
        from._rr = (d + 1) % 4;
        return true;
      }
    }
    return false;
  }

  offerFront(from, item)
  {
    var nb = this.getBuilding(from.getX() + DX[from.getDir()], from.getY() + DY[from.getDir()]);
    return nb != null && nb.accept(this, item, from.getX(), from.getY());
  }

  // Belt feed: finds the emptiest tower in a touching cluster that can take this item
  findAmmoSink(start, item)
  {
    var seen = {};
    var queue = [start];
    var best = null;
    var head = 0;
    seen[keyOf(start.getX(), start.getY())] = true;
    while (head < queue.length)
    {
      var t = queue[head];
      head++;
      var shots = this.shotsFor(t, item);
      if (shots > 0 && t.getAmmo() + shots <= TOWER_DEFS[t.getKind()].ammoMax && (best == null || t.getAmmo() < best.getAmmo()))
      {
        best = t;
      }
      var d = 0;
      for (d = 0; d < 4; d++)
      {
        var nb = this.getUpper(t.getX() + DX[d], t.getY() + DY[d]);
        if (nb != null && isTowerKind(nb.getKind()) && nb.isBuilt() && !seen[keyOf(nb.getX(), nb.getY())])
        {
          seen[keyOf(nb.getX(), nb.getY())] = true;
          queue.push(nb);
        }
      }
    }
    return best;
  }

  tapFeed(tap, item)
  {
    var tower = this.getUpper(tap.getX(), tap.getY());
    if (tower == null || !isTowerKind(tower.getKind()) || !tower.isBuilt())
    {
      return false;
    }
    var sink = this.findAmmoSink(tower, item);
    if (sink == null)
    {
      return false;
    }
    sink.addAmmo(this.shotsFor(sink, item));
    return true;
  }

  sell(item, x, y, count)
  {
    if (count === undefined)
    {
      count = 1;
    }
    var price = ITEMS[item].price * count;
    this.cashIn(price, x, y);
  }

  cashIn(amount, x, y)
  {
    this._credits += amount;
    this._sales.push({ t: this._time, amount: amount });
    this.addFloater(x + 0.5, y + 0.2, "+" + amount, "#ffe27a");
  }

  routeToGate(x, y)
  {
    var total = MAP_W * MAP_H;
    var parent = new Int32Array(total).fill(-1);
    var seen = new Uint8Array(total);
    var queue = new Int32Array(total);
    var head = 0;
    var tail = 0;
    var start = y * MAP_W + x;
    var goal = GATE_Y * MAP_W + GATE_X;
    queue[tail] = start;
    tail++;
    seen[start] = 1;
    while (head < tail && !seen[goal])
    {
      var cur = queue[head];
      head++;
      var cx = cur % MAP_W;
      var cy = Math.floor(cur / MAP_W);
      var d = 0;
      for (d = 0; d < 4; d++)
      {
        var nx = cx + DX[d];
        var ny = cy + DY[d];
        if (!this.isWalkable(LAYER_UNDER, nx, ny))
        {
          continue;
        }
        var ni = ny * MAP_W + nx;
        if (seen[ni])
        {
          continue;
        }
        seen[ni] = 1;
        parent[ni] = cur;
        queue[tail] = ni;
        tail++;
      }
    }
    if (!seen[goal])
    {
      return null;
    }
    var route = [];
    var node = goal;
    while (node != -1)
    {
      route.unshift({ x: node % MAP_W, y: Math.floor(node / MAP_W) });
      node = parent[node];
    }
    return route;
  }

  deliver(item, count, x, y)
  {
    if (this._wagon == null)
    {
      return;
    }
    var dock = this.getBuilding(Math.floor(x), Math.floor(y));
    if (dock == null || dock.getKind() != "trader")
    {
      dock = this._wagon;
    }
    dock.addCargo(ITEMS[item].price * count, count, true);
  }

  // ---- hand mining, tech, staffing

  getWagon()
  {
    return this._wagon;
  }

  getOrders()
  {
    return this._orders;
  }

  hasLab()
  {
    var i = 0;
    for (i = 0; i < this._buildings.length; i++)
    {
      if (this._buildings[i].getKind() == "lab" && this._buildings[i].isBuilt())
      {
        return true;
      }
    }
    return false;
  }

  hasTech(id)
  {
    if (this._tech[id])
    {
      return true;
    }
    return false;
  }

  getPickTier()
  {
    if (this._tech.picks2)
    {
      return 2;
    }
    if (this._tech.picks1)
    {
      return 1;
    }
    return 0;
  }

  getPick()
  {
    return PICKS[this.getPickTier()];
  }

  mineHaulTime()
  {
    var p = this.getPick();
    return p.cap * p.perItem;
  }

  techReason(id)
  {
    var t = TECH[id];
    if (this._tech[id])
    {
      return "Owned";
    }
    if (!this.hasLab())
    {
      return "Needs a Research Lab (Rooms menu)";
    }
    if (t.requires != null && !this._tech[t.requires])
    {
      return "Needs " + TECH[t.requires].name;
    }
    if (this._wins < t.minWins)
    {
      return "Needs " + t.minWins + " raid wins";
    }
    if (this._credits < t.cost)
    {
      return "Cannot afford";
    }
    return "";
  }

  cmdBuyTech(id)
  {
    var r = this.techReason(id);
    if (r != "")
    {
      return r;
    }
    this._credits -= TECH[id].cost;
    this._tech[id] = true;
    this.addLog("Researched " + TECH[id].name + ".");
    return "ok";
  }

  toolLockReason(id)
  {
    if (id == "dig" || id == "clear" || id == "erase" || id == "staff")
    {
      return "";
    }
    if (id == "expand")
    {
      if (this._expandCredits <= 0)
      {
        return "Win a raid to earn an expansion";
      }
      return "";
    }
    if (id == "trader")
    {
      return "";
    }
    if (this._wagon == null)
    {
      return "Build the Trade Wagon first";
    }
    if (id == "drill" && !this._tech.manned)
    {
      return "Needs Mounted Drill Rig (Upgrades)";
    }
    if (id == "autodrill" && !this._tech.auto)
    {
      return "Needs Steam Automaton (Upgrades)";
    }
    if (id == "tap" && !this._tech.autoload)
    {
      return "Needs Belt Loader Rig (Upgrades)";
    }
    return "";
  }

  mineReason(x, y)
  {
    if (this._wagon == null || !this._wagon.isBuilt())
    {
      return "Build the Trade Wagon first";
    }
    if (!inBounds(x, y))
    {
      return "Out of bounds";
    }
    if (!this.isUnlocked(x, y))
    {
      return "Beyond your claim";
    }
    if (this._tiles[y][x] != T_FLOOR)
    {
      return "Dig it out first";
    }
    var ore = this._ore[y][x];
    if (ore == 0)
    {
      return "No ore here";
    }
    if (ore == 2 && !this._unlockedIron)
    {
      return "Iron is locked. Win a raid first";
    }
    var node = this._nodeAt[y][x];
    if (node != null && node.isDepleted())
    {
      return "Node depleted, refilling (" + Math.floor(node.getFill() * 100) + "%)";
    }
    return "";
  }

  cmdMine(x, y)
  {
    var i = 0;
    for (i = 0; i < this._orders.length; i++)
    {
      if (this._orders[i].x == x && this._orders[i].y == y)
      {
        this._orders.splice(i, 1);
        return "ok";
      }
    }
    var why = this.mineReason(x, y);
    if (why != "")
    {
      return why;
    }
    var type = "copper";
    if (this._ore[y][x] == 2)
    {
      type = "iron";
    }
    this._orders.push({ x: x, y: y, type: type, occupied: false });
    return "ok";
  }

  isOrderActive(order)
  {
    return this._orders.indexOf(order) >= 0;
  }

  cmdToggleStaff(x, y)
  {
    var b = this.getBuilding(x, y);
    if (b == null || b.getKind() != "drill")
    {
      return "Not a mounted drill";
    }
    b.setEnabled(!b.isEnabled());
    if (!b.isEnabled() && b.getOperator() != null)
    {
      b.getOperator().release();
    }
    return "ok";
  }

  bfsFrom(sx, sy, sl)
  {
    var total = MAP_W * MAP_H * 2;
    var dist = new Int32Array(total).fill(-1);
    var parent = new Int32Array(total).fill(-1);
    if (!inBounds(sx, sy))
    {
      return { dist: dist, parent: parent };
    }
    var queue = new Int32Array(total);
    var head = 0;
    var tail = 0;
    var start = nodeIndex(sl, sx, sy);
    queue[tail] = start;
    tail++;
    dist[start] = 0;
    while (head < tail)
    {
      var cur = queue[head];
      head++;
      var l = nodeLayer(cur);
      var cx = nodeX(cur);
      var cy = nodeY(cur);
      var d = 0;
      for (d = 0; d < 4; d++)
      {
        var nx = cx + DX[d];
        var ny = cy + DY[d];
        if (this.isWalkable(l, nx, ny))
        {
          var ni = nodeIndex(l, nx, ny);
          if (dist[ni] == -1)
          {
            dist[ni] = dist[cur] + 1;
            parent[ni] = cur;
            queue[tail] = ni;
            tail++;
          }
        }
      }
      // Hatch: a tile open on both layers lets dwarves change layers
      var other = 1 - l;
      if (this.isWalkable(l, cx, cy) && this.isWalkable(other, cx, cy))
      {
        var oi = nodeIndex(other, cx, cy);
        if (dist[oi] == -1)
        {
          dist[oi] = dist[cur] + 1;
          parent[oi] = cur;
          queue[tail] = oi;
          tail++;
        }
      }
    }
    return { dist: dist, parent: parent };
  }

  pathFromBfs(res, tl, tx, ty)
  {
    var idx = nodeIndex(tl, tx, ty);
    if (res.dist[idx] < 0)
    {
      return null;
    }
    var path = [];
    var cur = idx;
    while (res.parent[cur] != -1)
    {
      path.unshift({ x: nodeX(cur), y: nodeY(cur), l: nodeLayer(cur) });
      cur = res.parent[cur];
    }
    return path;
  }

  findPathToWagon(sx, sy, sl)
  {
    if (this._wagon == null)
    {
      return null;
    }
    var res = this.bfsFrom(sx, sy, sl);
    var bestPath = null;
    var i = 0;
    for (i = 0; i < this._buildings.length; i++)
    {
      var b = this._buildings[i];
      if (b.getKind() != "trader" || !b.isBuilt())
      {
        continue;
      }
      var p = this.pathFromBfs(res, LAYER_UNDER, b.getX(), b.getY());
      if (p != null && (bestPath == null || p.length < bestPath.length))
      {
        bestPath = p;
      }
    }
    return bestPath;
  }

  findStaffingPost(sx, sy, sl)
  {
    var res = null;
    var best = null;
    var bestDist = 999999;
    var i = 0;
    for (i = 0; i < this._buildings.length; i++)
    {
      var b = this._buildings[i];
      if (b.getKind() != "drill" || !b.isBuilt() || !b.isEnabled() || b.getOperator() != null)
      {
        continue;
      }
      if (res == null)
      {
        res = this.bfsFrom(sx, sy, sl);
      }
      var d = res.dist[nodeIndex(LAYER_UNDER, b.getX(), b.getY())];
      if (d >= 0 && d < bestDist)
      {
        bestDist = d;
        best = b;
      }
    }
    if (best == null)
    {
      return null;
    }
    return { post: best, path: this.pathFromBfs(res, LAYER_UNDER, best.getX(), best.getY()) };
  }

  isPostValid(worker, b)
  {
    if (b == null)
    {
      return false;
    }
    return this.getBuilding(b.getX(), b.getY()) === b && b.isEnabled() && b.getOperator() === worker;
  }

  findMineOrder(sx, sy, sl)
  {
    if (this._orders.length == 0)
    {
      return null;
    }
    var res = this.bfsFrom(sx, sy, sl);
    var best = null;
    var bestDist = 999999;
    var i = 0;
    for (i = 0; i < this._orders.length; i++)
    {
      var o = this._orders[i];
      var on = this._nodeAt[o.y][o.x];
      if (o.occupied || (on != null && on.isDepleted()))
      {
        continue;
      }
      var d = res.dist[nodeIndex(LAYER_UNDER, o.x, o.y)];
      if (d >= 0 && d < bestDist)
      {
        bestDist = d;
        best = o;
      }
    }
    if (best == null)
    {
      return null;
    }
    return { order: best, path: this.pathFromBfs(res, LAYER_UNDER, best.x, best.y) };
  }

  getHint()
  {
    if (this._wagon == null)
    {
      return "Step 1: open Economy > Trade Wagon and place it inside the mountain near the Gate.";
    }
    if (!this._wagon.isBuilt())
    {
      return "A dwarf is building the Trade Wagon. Meanwhile, Actions > Dig toward the orange glints.";
    }
    if (this._expandCredits > 0)
    {
      return "You can expand the map: Actions > Expand, then click a glowing block.";
    }
    var towerCount = 0;
    var dry = true;
    var t = 0;
    for (t = 0; t < this._buildings.length; t++)
    {
      var tb = this._buildings[t];
      if (isTowerKind(tb.getKind()) && tb.isBuilt())
      {
        towerCount += 1;
        if (tb.getAmmo() > 0)
        {
          dry = false;
        }
      }
    }
    if (towerCount > 0 && dry && this.stockOf("iron") + this.stockOf("copper") + this.stockOf("ironBar") == 0)
    {
      return "Your towers are dry. Belt ore or bars into a Storage and a dwarf will restock them.";
    }
    var drills = 0;
    var i = 0;
    for (i = 0; i < this._buildings.length; i++)
    {
      if (this._buildings[i].getKind() == "drill" || this._buildings[i].getKind() == "autodrill")
      {
        drills += 1;
      }
    }
    if (this._orders.length == 0 && drills == 0)
    {
      return "Dig toward the orange glints (Actions > Dig), then mark the ore with Actions > Mine ore.";
    }
    if (!this.hasLab())
    {
      return "Excavate a 4x3 room (Dig, Surface view, inside the mountain) and build a Research Lab (Rooms, R rotates).";
    }
    if (!this._tech.picks1)
    {
      return "Next: Hardened Picks (100c) in Upgrades.";
    }
    if (!this._tech.manned)
    {
      return "Next: Mounted Drill Rig (250c) in Upgrades.";
    }
    if (drills == 0)
    {
      return "Place a Mounted Drill on an ore node. A dwarf has to man it. Belt its output to the wagon.";
    }
    if (towerCount == 0)
    {
      return "Defense: smelt copper into bars, belt them into a Storage, then build a Crossbow outside the Gate. Dwarves man towers during raids.";
    }
    if (!this._tech.auto)
    {
      return "Later: Steam Automaton (900c, 2 raid wins) frees dwarves from drill duty.";
    }
    return "";
  }

  // ---- storage stock and building costs

  stockOf(item)
  {
    var total = 0;
    var i = 0;
    for (i = 0; i < this._buildings.length; i++)
    {
      var b = this._buildings[i];
      if (b.getKind() == "storage" && b.isBuilt() && b.getStock()[item] !== undefined)
      {
        total += b.getStock()[item];
      }
    }
    return total;
  }

  takeFromStorage(item, n)
  {
    var taken = 0;
    var i = 0;
    for (i = 0; i < this._buildings.length && taken < n; i++)
    {
      var b = this._buildings[i];
      if (b.getKind() == "storage" && b.isBuilt())
      {
        taken += b.removeStock(item, n - taken);
      }
    }
    return taken;
  }

  // Returns how many items did not fit
  stashItem(item, n)
  {
    var left = n;
    var i = 0;
    for (i = 0; i < this._buildings.length && left > 0; i++)
    {
      var b = this._buildings[i];
      if (b.getKind() == "storage" && b.isBuilt())
      {
        left -= b.addStock(item, left);
      }
    }
    return left;
  }

  itemsReason(items)
  {
    if (items === undefined)
    {
      return "";
    }
    var id = "";
    for (id in items)
    {
      if (this.stockOf(id) < items[id])
      {
        return "Needs " + items[id] + " " + ITEMS[id].name + " in Storage";
      }
    }
    return "";
  }

  payItems(items)
  {
    if (items === undefined)
    {
      return;
    }
    var id = "";
    for (id in items)
    {
      this.takeFromStorage(id, items[id]);
    }
  }

  // ---- towers: ammo, crews, firing

  shotsFor(tower, item)
  {
    var s = TOWER_DEFS[tower.getKind()].ammo[item];
    if (s === undefined)
    {
      return 0;
    }
    return s;
  }

  hasTapBelow(b)
  {
    var under = this.getBuilding(b.getX(), b.getY());
    return under != null && under.getKind() == "tap" && under.isBuilt();
  }

  // Fire-rate multiplier: a crew dwarf scales with skill, a belt tap is a flat discount, nothing means no fire
  towerRate(b)
  {
    var op = b.getOperator();
    if (op != null && op.isGunning())
    {
      return op.speedMul(TOWER_SKILL);
    }
    if (this.hasTapBelow(b))
    {
      return AUTO_FIRE_RATE;
    }
    return 0;
  }

  towerLowAmmo(b)
  {
    return Math.floor(TOWER_DEFS[b.getKind()].ammoMax * TOWER_LOW_AMMO);
  }

  bestAmmoItem(tower)
  {
    var def = TOWER_DEFS[tower.getKind()];
    var best = null;
    var bestShots = 0;
    var id = "";
    for (id in def.ammo)
    {
      if (def.ammo[id] > bestShots && this.stockOf(id) > 0)
      {
        bestShots = def.ammo[id];
        best = id;
      }
    }
    return best;
  }

  fetchAmount(tower, item)
  {
    var def = TOWER_DEFS[tower.getKind()];
    var shots = def.ammo[item];
    if (shots === undefined)
    {
      return 0;
    }
    var room = def.ammoMax - tower.getAmmo();
    return Math.min(TOWER_HAUL_ITEMS, Math.floor(room / shots));
  }

  fireTower(b, target)
  {
    var def = TOWER_DEFS[b.getKind()];
    var i = 0;
    b.addAmmo(-1);
    if (def.aoe > 0)
    {
      var tx = target.getX();
      var ty = target.getY();
      for (i = 0; i < this._enemies.length; i++)
      {
        var e = this._enemies[i];
        if (e.isDead() || (e.isFlying() && !def.air))
        {
          continue;
        }
        var dx = e.getX() - tx;
        var dy = e.getY() - ty;
        if (dx * dx + dy * dy <= def.aoe * def.aoe)
        {
          e.hurt(def.damage);
          if (def.slow > 0)
          {
            e.slow(def.slow, def.slowTime);
          }
        }
      }
      this.addBlast(tx, ty, def.aoe);
    }
    else
    {
      target.hurt(def.damage);
      if (def.slow > 0)
      {
        target.slow(def.slow, def.slowTime);
      }
    }
    this.addShot(b.getX() + 0.5, b.getY() + 0.5, target.getX(), target.getY());
    var op = b.getOperator();
    if (op != null && op.isGunning())
    {
      op.gainXp(this, TOWER_SKILL, TOWER_SHOT_XP);
    }
  }

  isTowerManned(worker, t)
  {
    if (t == null || this._buildings.indexOf(t) < 0 || !t.isBuilt())
    {
      return false;
    }
    return t.getOperator() === worker && this._raid != null;
  }

  isHaulValid(worker)
  {
    var t = worker.getTower();
    if (t == null || this._buildings.indexOf(t) < 0 || !t.isBuilt())
    {
      return false;
    }
    if (worker.getPost() === t)
    {
      return t.getOperator() === worker;
    }
    return t.getRestocker() === worker;
  }

  // Nearest surface tile touching the tower that a dwarf can stand on
  standTile(res, tower)
  {
    var best = null;
    var bestDist = 999999;
    var n = 0;
    for (n = 0; n < 4; n++)
    {
      var ax = tower.getX() + DX[n];
      var ay = tower.getY() + DY[n];
      if (!inBounds(ax, ay))
      {
        continue;
      }
      var d = res.dist[nodeIndex(LAYER_SURFACE, ax, ay)];
      if (d >= 0 && d < bestDist)
      {
        bestDist = d;
        best = { x: ax, y: ay, dist: d };
      }
    }
    return best;
  }

  pathToTowerStand(sx, sy, sl, tower)
  {
    var res = this.bfsFrom(sx, sy, sl);
    var stand = this.standTile(res, tower);
    if (stand == null)
    {
      return null;
    }
    return this.pathFromBfs(res, LAYER_SURFACE, stand.x, stand.y);
  }

  nearestStorageWith(res, item)
  {
    var best = null;
    var bestDist = 999999;
    var i = 0;
    for (i = 0; i < this._buildings.length; i++)
    {
      var b = this._buildings[i];
      if (b.getKind() != "storage" || !b.isBuilt() || b.getStock()[item] === undefined || b.getStock()[item] <= 0)
      {
        continue;
      }
      var d = res.dist[nodeIndex(LAYER_UNDER, b.getX(), b.getY())];
      if (d >= 0 && d < bestDist)
      {
        bestDist = d;
        best = b;
      }
    }
    return best;
  }

  planFetch(sx, sy, sl, tower)
  {
    var item = this.bestAmmoItem(tower);
    if (item == null)
    {
      return null;
    }
    var res = this.bfsFrom(sx, sy, sl);
    var store = this.nearestStorageWith(res, item);
    if (store == null)
    {
      return null;
    }
    return { item: item, path: this.pathFromBfs(res, LAYER_UNDER, store.getX(), store.getY()) };
  }

  // Crew jobs. During a raid an unmanned tower wants an operator; otherwise low towers want a restock run.
  findTowerJob(sx, sy, sl)
  {
    var res = null;
    var i = 0;
    var bestTower = null;
    var bestStand = null;
    var bestDist = 999999;
    if (this._raid != null)
    {
      for (i = 0; i < this._buildings.length; i++)
      {
        var b = this._buildings[i];
        if (!isTowerKind(b.getKind()) || !b.isBuilt() || b.getOperator() != null)
        {
          continue;
        }
        if (b.getAmmo() <= 0 && this.bestAmmoItem(b) == null)
        {
          continue;
        }
        if (res == null)
        {
          res = this.bfsFrom(sx, sy, sl);
        }
        var stand = this.standTile(res, b);
        if (stand != null && stand.dist < bestDist)
        {
          bestDist = stand.dist;
          bestTower = b;
          bestStand = stand;
        }
      }
      if (bestTower != null)
      {
        return { mode: "man", tower: bestTower, path: this.pathFromBfs(res, LAYER_SURFACE, bestStand.x, bestStand.y) };
      }
    }
    var bestItem = null;
    var bestStore = null;
    for (i = 0; i < this._buildings.length; i++)
    {
      var t = this._buildings[i];
      if (!isTowerKind(t.getKind()) || !t.isBuilt() || t.getOperator() != null || t.getRestocker() != null)
      {
        continue;
      }
      if (t.getAmmo() > TOWER_DEFS[t.getKind()].ammoMax * TOWER_RESTOCK_BELOW)
      {
        continue;
      }
      var item = this.bestAmmoItem(t);
      if (item == null || this.fetchAmount(t, item) <= 0)
      {
        continue;
      }
      if (res == null)
      {
        res = this.bfsFrom(sx, sy, sl);
      }
      var store = this.nearestStorageWith(res, item);
      if (store == null)
      {
        continue;
      }
      var d = res.dist[nodeIndex(LAYER_UNDER, store.getX(), store.getY())];
      if (d >= 0 && d < bestDist)
      {
        bestDist = d;
        bestTower = t;
        bestItem = item;
        bestStore = store;
      }
    }
    if (bestTower == null)
    {
      return null;
    }
    return { mode: "restock", tower: bestTower, item: bestItem, path: this.pathFromBfs(res, LAYER_UNDER, bestStore.getX(), bestStore.getY()) };
  }

  towerStatus(b)
  {
    var def = TOWER_DEFS[b.getKind()];
    var text = def.name + " ammo " + b.getAmmo() + "/" + def.ammoMax + ". ";
    var op = b.getOperator();
    if (op != null && op.isGunning())
    {
      text += "Manned by " + op.getName() + " (fire rate x" + op.speedMul(TOWER_SKILL).toFixed(2) + "). ";
    }
    else if (this.hasTapBelow(b))
    {
      text += "Belt-fed, fires at x" + AUTO_FIRE_RATE.toFixed(2) + ", no dwarf needed. ";
    }
    else
    {
      text += "Unmanned: a dwarf with Craftsmanship on mans it during raids. ";
    }
    var names = [];
    var id = "";
    for (id in def.ammo)
    {
      names.push(ITEMS[id].name);
    }
    return text + "Ammo: " + names.join(", ") + ".";
  }

  // ---- raids

  getScout(rivalId)
  {
    var r = RIVALS[rivalId];
    var lines = [];
    var i = 0;
    for (i = 0; i < r.waves.length; i++)
    {
      var label = "Wave " + (i + 1) + ": ";
      if (i == r.waves.length - 1)
      {
        label = "Boss wave: ";
      }
      if (i == this._hidden[rivalId])
      {
        lines.push(label + "??? (hidden)");
      }
      else
      {
        var names = [];
        var w = 0;
        for (w = 0; w < r.waves[i].length; w++)
        {
          names.push(ENEMY_TYPES[r.waves[i][w][0]].name);
        }
        lines.push(label + names.join(", "));
      }
    }
    return lines;
  }

  difficultyMul(difficulty)
  {
    return 1 + DIFFICULTY_STEP * (difficulty - 1);
  }

  enemyCountMul(buyin)
  {
    return Math.pow(buyin / MIN_BUYIN, BUYIN_COUNT_EXP);
  }

  payoutFor(buyin, difficulty)
  {
    return Math.floor(buyin * BASE_RETURN * this.difficultyMul(difficulty));
  }

  premiumFor(buyin, difficulty)
  {
    return Math.max(1, Math.floor((1 + buyin / 200) * this.difficultyMul(difficulty)));
  }

  cmdStartRaid(rivalId, buyin, difficulty)
  {
    if (difficulty === undefined)
    {
      difficulty = 1;
    }
    if (this._raid != null)
    {
      return "A raid is already running";
    }
    if (buyin < MIN_BUYIN)
    {
      return "Buy-in too small";
    }
    if (difficulty < 1 || difficulty > this.getTier())
    {
      return "Difficulty locked";
    }
    if (this._credits < buyin)
    {
      return "Cannot afford the buy-in";
    }
    this._credits -= buyin;
    var def = RIVALS[rivalId];
    var countMul = this.enemyCountMul(buyin);
    var waves = [];
    var i = 0;
    for (i = 0; i < def.waves.length; i++)
    {
      var list = [];
      var g = 0;
      for (g = 0; g < def.waves[i].length; g++)
      {
        var count = Math.round(def.waves[i][g][1] * countMul);
        if (count < 1)
        {
          count = 1;
        }
        var c = 0;
        for (c = 0; c < count; c++)
        {
          list.push(def.waves[i][g][0]);
        }
      }
      var s = 0;
      for (s = list.length - 1; s > 0; s--)
      {
        var r = Math.floor(nextRandom() * (s + 1));
        var tmp = list[s];
        list[s] = list[r];
        list[r] = tmp;
      }
      waves.push(list);
    }
    this._raid = {
      rivalId: rivalId,
      buyin: buyin,
      difficulty: difficulty,
      waves: waves,
      waveIdx: -1,
      queue: [],
      state: "delay",
      delay: RAID_FIRST_DELAY,
      spawnT: 0,
      hpMul: this.difficultyMul(difficulty)
    };
    this.addLog("Raid started against " + def.name + ". Buy-in paid: " + buyin + ". Difficulty " + difficulty + ".");
    return "ok";
  }

  spawnEnemy(type)
  {
    if (this._flowDirty)
    {
      this.recomputeFlow();
    }
    var options = [];
    var x = 0;
    for (x = 1; x < MAP_W - 1; x++)
    {
      if (this._dist[MAP_H - 1][x] >= 0)
      {
        options.push(x);
      }
    }
    if (options.length == 0)
    {
      return;
    }
    var pick = options[Math.floor(nextRandom() * options.length)];
    this._enemies.push(new Enemy(type, pick + 0.5, MAP_H - 0.5, this._raid.hpMul));
  }

  updateRaid(dt)
  {
    var raid = this._raid;
    if (raid == null)
    {
      return;
    }
    if (raid.state == "delay")
    {
      raid.delay -= dt;
      if (raid.delay <= 0)
      {
        raid.waveIdx += 1;
        raid.queue = raid.waves[raid.waveIdx].slice();
        raid.state = "spawning";
        raid.spawnT = 0;
        this.addLog("Wave " + (raid.waveIdx + 1) + " of " + raid.waves.length + " incoming!");
      }
      return;
    }
    if (raid.state == "spawning")
    {
      raid.spawnT -= dt;
      if (raid.spawnT <= 0 && raid.queue.length > 0)
      {
        this.spawnEnemy(raid.queue.shift());
        raid.spawnT = 0.55;
      }
      if (raid.queue.length == 0)
      {
        raid.state = "clearing";
      }
      return;
    }
    if (raid.state == "clearing")
    {
      if (this._enemies.length == 0)
      {
        if (raid.waveIdx >= raid.waves.length - 1)
        {
          this.winRaid();
        }
        else
        {
          raid.state = "delay";
          raid.delay = 6;
        }
      }
    }
  }

  enemyReachedGate()
  {
    if (this._raid == null)
    {
      return;
    }
    var def = RIVALS[this._raid.rivalId];
    this._enemies = [];
    this._losses += 1;
    var taunt = def.taunts[Math.floor(nextRandom() * def.taunts.length)];
    this.addLog("RAID LOST. Buy-in forfeited. " + taunt);
    this._raid = null;
    this.rollHidden();
  }

  winRaid()
  {
    var raid = this._raid;
    var def = RIVALS[raid.rivalId];
    var pot = this.payoutFor(raid.buyin, raid.difficulty);
    this._credits += pot;
    var premiumGain = this.premiumFor(raid.buyin, raid.difficulty);
    this._premium[def.premium] += premiumGain;
    this._wins += 1;
    this._regions += 1;
    this._expandCredits += 1;
    this.addLog("RAID WON! Pot: " + pot + " credits and " + premiumGain + " " + def.premiumName + ". Claim new land: Actions > Expand.");
    if (!this._unlockedIron)
    {
      this._unlockedIron = true;
      this.addLog("Iron nodes unlocked. Difficulty " + this.getTier() + " is now available.");
    }
    else
    {
      this.addLog("Difficulty " + this.getTier() + " is now available.");
    }
    this._raid = null;
    this.rollHidden();
  }

  findTarget(x, y, range, def)
  {
    var best = null;
    var bestFlow = 9999999;
    var i = 0;
    for (i = 0; i < this._enemies.length; i++)
    {
      var e = this._enemies[i];
      if (e.isDead())
      {
        continue;
      }
      if (e.isFlying() && !def.air)
      {
        continue;
      }
      var dx = e.getX() - x;
      var dy = e.getY() - y;
      if (dx * dx + dy * dy <= range * range)
      {
        if (!e.isFlying() && !def.arc && !this.sightClear(x, y, e.getX(), e.getY()))
        {
          continue;
        }
        var f = this.flowDistAt(Math.floor(e.getX()), Math.floor(e.getY()));
        if (f < bestFlow)
        {
          bestFlow = f;
          best = e;
        }
      }
    }
    return best;
  }

  // ---- main step

  update(dt)
  {
    var i = 0;
    this._time += dt;
    if (this._flowDirty)
    {
      this.recomputeFlow();
    }
    this._credits += this._regions * REGION_INCOME * dt;
    this._comfortT -= dt;
    if (this._comfortT <= 0)
    {
      this._comfortT = COMFORT_INTERVAL;
      this.updateHousing();
    }
    for (i = 0; i < this._nodes.length; i++)
    {
      this._nodes[i].update(dt);
    }

    for (i = 0; i < this._buildings.length; i++)
    {
      if (this._buildings[i].isBuilt())
      {
        this._buildings[i].update(this, dt);
      }
    }
    for (i = 0; i < this._workers.length; i++)
    {
      this._workers[i].update(this, dt);
    }
    this.updateRaid(dt);
    for (i = 0; i < this._enemies.length; i++)
    {
      this._enemies[i].update(this, dt);
    }
    var alive = [];
    for (i = 0; i < this._enemies.length; i++)
    {
      if (!this._enemies[i].isDead())
      {
        alive.push(this._enemies[i]);
      }
      else
      {
        this.addCorpse(this._enemies[i]);
      }
    }
    this._enemies = alive;

    var keepF = [];
    for (i = 0; i < this._floaters.length; i++)
    {
      var f = this._floaters[i];
      f.life -= dt;
      f.y -= 0.5 * dt;
      if (f.life > 0)
      {
        keepF.push(f);
      }
    }
    this._floaters = keepF;

    var keepS = [];
    for (i = 0; i < this._shots.length; i++)
    {
      this._shots[i].life -= dt;
      if (this._shots[i].life > 0)
      {
        keepS.push(this._shots[i]);
      }
    }
    this._shots = keepS;

    var keepB = [];
    for (i = 0; i < this._blasts.length; i++)
    {
      this._blasts[i].life -= dt;
      if (this._blasts[i].life > 0)
      {
        keepB.push(this._blasts[i]);
      }
    }
    this._blasts = keepB;

    var keepC = [];
    for (i = 0; i < this._corpses.length; i++)
    {
      this._corpses[i].t += dt;
      if (this._corpses[i].t < this._corpses[i].life)
      {
        keepC.push(this._corpses[i]);
      }
    }
    this._corpses = keepC;

    var keepSales = [];
    for (i = 0; i < this._sales.length; i++)
    {
      if (this._time - this._sales[i].t < 30)
      {
        keepSales.push(this._sales[i]);
      }
    }
    this._sales = keepSales;
  }
}

// ======================================================================
// Everything below touches the browser. Skipped when run headless.
