  function refreshBoard()
  {
    var r = RIVALS[selectedRival];
    var tabButtons = tabs.getElementsByTagName("button");
    var i = 0;
    for (i = 0; i < tabButtons.length; i++)
    {
      if (tabButtons[i].getAttribute("data-rival") == selectedRival)
      {
        tabButtons[i].className = "active";
      }
      else
      {
        tabButtons[i].className = "";
      }
    }
    var lines = game.getScout(selectedRival);
    var html = "<p><i>" + r.blurb + "</i></p><ul>";
    for (i = 0; i < lines.length; i++)
    {
      html += "<li>" + lines[i] + "</li>";
    }
    html += "</ul><p>Premium prize: <b>" + r.premiumName + "</b> (not spendable yet).</p>";
    document.getElementById("scout").innerHTML = html;
    if (difficulty > game.getTier())
    {
      difficulty = game.getTier();
    }
    document.getElementById("buyin").textContent = buyin + " credits";
    document.getElementById("difficulty").textContent = difficulty + " (max " + game.getTier() + ")";
    document.getElementById("payoutInfo").innerHTML = "Enemy count x" + game.enemyCountMul(buyin).toFixed(2) + " (buy-in). Enemy strength x" + game.difficultyMul(difficulty).toFixed(2) + " (difficulty).<br>Win pays " + game.payoutFor(buyin, difficulty) + " plus " + game.premiumFor(buyin, difficulty) + " " + r.premiumName + " and a map expansion. Lose: buy-in gone.";
  }

